window.POEM_DB=window.POEM_DB||{};POEM_DB["song_033"]={"n":"魏了翁","dyn":"宋","poems":[{"t":"次韵张太博得余所遗二程先生集辩二程戏邵子语","f":"五言古诗","c":["文字未科斗，图书未龟龙。","粲然天地间，此理触处逢。","是谓象之祖，而为数之宗。","昊牺古神圣，先得人所同。","文因而繇之，旦出亦并雄。","讫于我孔圣，天命滋益恭。","浑然一理贯，密察而从容。","辞变与象占，四者固所崇。","推辞以知变，象占在其中。","荒荒秦汉后，学者昧所从。","不以灾异会，则以虚无通。","天开周程子，易道乃复东。","动静静复动，终始始而终。","上承千年绪，下起百世风。","同时有邵子，讲道于伊嵩。","天地之运化，阴阳之无穷。","即物验消长，先几知吉凶。","邵子极道数，独立几无戎。","二程自周孔，为时开梦梦。","其归则一耳，昧者结忡忡。","学之将柰何，矧余倍颛蒙。","要知羲皇心，须踏周孔踪。"]},{"t":"李提刑李参政再和招鹤诗再用韵以谢 其一","f":"七言绝句","c":["静看瀺灂几游鳞，争似玄裳缟袂生。","几度有书招不至，应惭侧翅傍他人。"]},{"t":"二月十九日席上赋 其四","f":"七言绝句","c":["年光又见一百五，春意才馀十二三。","节物催人浑不觉，谩随白堕看红酣。"]},{"t":"二月十九日席上赋 其三","f":"七言绝句","c":["昨宵浑不遣花知，畚锸和根带露移。","睡里骊珠醉中屐，想花失在未醒时。"]},{"t":"二月十九日席上赋 其二","f":"七言绝句","c":["露渍风揉娇婀娜，烟笼日炙绿鬅鬙。","风流名字时方污，亦为仪容太不矜。"]},{"t":"二月十九日席上赋 其一","f":"七言绝句","c":["野荼蘼发雪堆墙，草牡丹开月照梁。","世眼都随人毁誉，不知底处是真香。"]},{"t":"八月七日被命上会稽沿途所历拙于省记为韵语以记之舟中马上随得随书不复叙次 其十二","f":"七言绝句","c":["沛宫魂魄只思归，不道苍梧与会稽。","帝后精神天陟降，宁分南北与东西。"]},{"t":"八月七日被命上会稽沿途所历拙于省记为韵语以记之舟中马上随得随书不复叙次 其十七","f":"七言绝句","c":["越台雨壑压层巅，下有蓬莱镇越颜。","拄笏正当秦望岭，绕城总号会稽山。"]},{"t":"八月七日被命上会稽沿途所历拙于省记为韵语以记之舟中马上随得随书不复叙次 其八","f":"七言绝句","c":["次从祐阜至思崇，攒影俱分上下宫。","闻似八陵旧山水，地垂西北耸南东。"]},{"t":"八月七日被命上会稽沿途所历拙于省记为韵语以记之舟中马上随得随书不复叙次 其十九","f":"七言绝句","c":["会稽太守约重论，解后新安共一尊。","踏月归来已丁夜，又乘朱舫出西门。"]},{"t":"八月七日被命上会稽沿途所历拙于省记为韵语以记之舟中马上随得随书不复叙次 其十五","f":"七言绝句","c":["吴会元从二郡呼，今将吴会指姑苏。","稽山当取旧经说，禹穴难凭遁甲图。"]},{"t":"八月七日被命上会稽沿途所历拙于省记为韵语以记之舟中马上随得随书不复叙次 其六","f":"七言绝句","c":["三十六源光夺鉴，九千馀顷稻盈车。","何年使客徼微利，不管稽阴数万家。"]},{"t":"八月七日被命上会稽沿途所历拙于省记为韵语以记之舟中马上随得随书不复叙次 其四","f":"七言绝句","c":["越州官吏出郊迎，骑从香舆舍妙明。","只把一诚将圣孝，尧眉舜目俨墙羹。"]},{"t":"八月七日被命上会稽沿途所历拙于省记为韵语以记之舟中马上随得随书不复叙次 其一","f":"七言绝句","c":["篾帆松艇趁潮生，隔岸平畴唤得应。","上到渡头失欢喜，泥行十里是西兴。"]},{"t":"八月七日被命上会稽沿途所历拙于省记为韵语以记之舟中马上随得随书不复叙次 其二","f":"七言绝句","c":["紫帏青伞杂旗旌，乌帽银挝从鼓钲。","导哄略如州别驾，无人知是汉庭卿。"]},{"t":"八月七日被命上会稽沿途所历拙于省记为韵语以记之舟中马上随得随书不复叙次 其十八","f":"七言绝句","c":["微之曾谪会稽居，州宅诗联画不如。","绕阁烟岚新雨后，满山楼阁上灯初。"]},{"t":"八月七日被命上会稽沿途所历拙于省记为韵语以记之舟中马上随得随书不复叙次 其十三","f":"七言绝句","c":["海邦气候异中州，襆被来时八月秋。","满枕松声眠月露，夜深仍与被为仇。"]},{"t":"八月七日被命上会稽沿途所历拙于省记为韵语以记之舟中马上随得随书不复叙次 其十","f":"七言绝句","c":["周官虽有墓为尸，细考元非墓祭仪。","九十年閒雠未复，陵■杂用最堪悲。"]},{"t":"八月七日被命上会稽沿途所历拙于省记为韵语以记之舟中马上随得随书不复叙次 其九","f":"七言绝句","c":["一位肴羞酒一卮，祠官熏灌祝陈词。","降升六拜焚词罢，六日精神用一时。"]},{"t":"八月七日被命上会稽沿途所历拙于省记为韵语以记之舟中马上随得随书不复叙次 其十一","f":"七言绝句","c":["新妇尖连赵家墺，憩龙山望上皇村。","若言此兆为前定，人事是非都不论。"]},{"t":"八月七日被命上会稽沿途所历拙于省记为韵语以记之舟中马上随得随书不复叙次 其十四","f":"七言绝句","c":["禹穴元从一罅通，禹陵元在乱山中。","饮泉窆石皆如此，误却东游太史公。"]},{"t":"八月七日被命上会稽沿途所历拙于省记为韵语以记之舟中马上随得随书不复叙次 其五","f":"七言绝句","c":["御香三日出斋庐，骑至城东下鉴湖。","瀰望湖田连荡地，菱花面目半模糊。"]},{"t":"八月七日被命上会稽沿途所历拙于省记为韵语以记之舟中马上随得随书不复叙次 其十六","f":"七言绝句","c":["千秋旧址益鸿禧，敕额祠宫盛一时。","遗迹犹存贺公宅，丰碑新敞越王祠。"]},{"t":"十二月九日雪融夜起达旦","f":"七言绝句","c":["远钟入枕雪初晴，衾铁棱棱梦不成。","起傍梅花读周易，一窗明月四檐声。"]},{"t":"十二月二十七日宰执率百官请大行皇帝谥于南郊曰宁宗纪事 其四","f":"七言绝句","c":["却向慈云岭上还，梅花合道日笼山。","马蹄十里摇归梦，疑在小园松竹间。"]},{"t":"十二月二十七日宰执率百官请大行皇帝谥于南郊曰宁宗纪事 其三","f":"七言绝句","c":["遇雨权将屋作坛，昊天神主位中閒。","吉凶异制今参用，今古殊宜亦并班。"]},{"t":"十二月二十七日宰执率百官请大行皇帝谥于南郊曰宁宗纪事 其二","f":"七言绝句","c":["礼属群趋上宰前，两郎奉册侍臣宣。","坛前拜跪升烟罢，随处群工署奏篇。"]},{"t":"十二月二十七日宰执率百官请大行皇帝谥于南郊曰宁宗纪事 其一","f":"七言绝句","c":["骑至南郊晓色苍，须臾陪拜俨成行。","两班吉带罗朱紫，惟有斋官服冕裳。"]},{"t":"十八日上寿退赐坐十九日贡院锡宴二十一日紫宸殿御筵即事 其七","f":"七言绝句","c":["十七年间作外臣，重来三日齿嘉宾。","天颜不减当年泽，点检同朝共五人。"]},{"t":"十八日上寿退赐坐十九日贡院锡宴二十一日紫宸殿御筵即事 其六","f":"七言绝句","c":["蛾眉班捲戴花回，遥望君王玉色开。","画楯诸班谢茶酒，尻高首下一声雷。"]},{"t":"十八日上寿退赐坐十九日贡院锡宴二十一日紫宸殿御筵即事 其五","f":"七言绝句","c":["再坐犹馀四屈卮，筋驽肉痹股生胝。","侍臣醉饱皇欢洽，更看终场角牴嬉。"]},{"t":"十八日上寿退赐坐十九日贡院锡宴二十一日紫宸殿御筵即事 其四","f":"七言绝句","c":["蹴鞠寻橦列广庭，吹丝按竹布前荣。","卿郎朵殿浑无见，只听时时万岁声。"]},{"t":"十八日上寿退赐坐十九日贡院锡宴二十一日紫宸殿御筵即事 其三","f":"七言绝句","c":["有次鞭鞘陆续鸣，赭袍当殿万簪缨。","群臣拜舞分行坐，十味肴羞酒五行。"]},{"t":"十八日上寿退赐坐十九日贡院锡宴二十一日紫宸殿御筵即事 其二","f":"七言绝句","c":["严妆列卫启宸居，百辟滔滔若贯鱼。","后幄宰臣先奏事，犹随郎从立前除。"]},{"t":"十八日上寿退赐坐十九日贡院锡宴二十一日紫宸殿御筵即事 其一","f":"七言绝句","c":["珂伞摇心梦不成，忽听吏皂放衙声。","吹灯拨火供晨粥，趁到皇城恰六更。"]},{"t":"十日夜闻风声","f":"七言绝句","c":["雪尽冰澌涕亦晴，布衾纸帐复求成。","卷书拟续前宵梦，一夜狂风撼户声。"]},{"t":"万州守潘拉登鲁池观荷花荔枝 其二","f":"七言绝句","c":["分随猿鹤老隈支，趋诏重来两鬓丝。","解后一觞莫辞凸，能禁二十载差池。"]},{"t":"万州守潘拉登鲁池观荷花荔枝 其一","f":"七言绝句","c":["密林和雨剪离支，曲径留阴切藕丝。","自入渝涪山色恶，眼明见此鲁家池。"]},{"t":"三峡桥","f":"七言绝句","c":["英云皓雨泻明蠲，题作人间第六泉。","拟把谷帘从黜降，却将此水为超迁。"]},{"t":"于眉州挽诗 其一","f":"七言绝句","c":["士为谋身蛇有足，人于嚣讼鼠无牙。","狱书一落于公手，不识从来豪大家。"]},{"t":"于眉州挽诗 其二","f":"七言绝句","c":["南浦冬阴翻手雨，湓江春涨打头风。","乖逢命耳吾何戚，赢得三州桃李丛。"]},{"t":"于眉州挽诗 其三","f":"七言绝句","c":["老雁长云横蜀道，归鸦落日倚江城。","摩挲少日生祠记，忍听虞歌薤露声。"]},{"t":"子益教授再用韵赋弈有审机从谏之诲某复和呈 其二","f":"七言绝句","c":["古人用众水如持，不为常安不虑危。","违谏伏波终自困，捍羌充国本无奇。"]},{"t":"子益教授再用韵赋弈有审机从谏之诲某复和呈 其一","f":"七言绝句","c":["从衡腷膊竞相酬，伺击羸行纬复游。","或把疑兵胜淝水，或乘猛势失荆州。"]},{"t":"书所见闻示诸友 其三","f":"七言绝句","c":["一从轻弃五边州，所恃藩篱仅武休。","又谓武休无足恃，并捐洋汉守金牛。"]},{"t":"书所见闻示诸友 其一","f":"七言绝句","c":["行到青天最上头，蜀人争看锦衣游。","谁知一夜北风恶，吹起家山万斛愁。"]},{"t":"书所见闻示诸友 其五","f":"七言绝句","c":["死城陷阵已长休，捍虏鸠民亦漫忧。","局外閒人倚江立，全躯保室信良谋。"]},{"t":"书所见闻示诸友 其四","f":"七言绝句","c":["金缯啖虏已无谋，况恃空言废内修。","师卦在中惟九二，曾闻帷幄授成筹。"]},{"t":"书所见闻示诸友 其二","f":"七言绝句","c":["闻说奔军闯阆州，馀州民溃去如流。","亲曾见虎诚堪怖，只为狐惊亦可羞。"]},{"t":"书遂宁何氏稳兴斋","f":"七言绝句","c":["巫峡孤舟嫌太重，山阳小艇又偏轻。","直须装载停匀着，更要其间御者平。"]},{"t":"以使事过成都讫事而归虞万州成都尉高表兄拉访灵泉宰高表兄风雨连明遂谒朱祭酒祠即事赋 其二","f":"七言绝句","c":["青灯相对同胞弟，白酒交酬异姓兄。","风雨似知人有约，终宵都作对床声。"]},{"t":"以使事过成都讫事而归虞万州成都尉高表兄拉访灵泉宰高表兄风雨连明遂谒朱祭酒祠即事赋 其三","f":"七言绝句","c":["无事江流到处平，无言天运四时新。","真仙此意何曾间，直到如今瞪视人。"]},{"t":"以使事过成都讫事而归虞万州成都尉高表兄拉访灵泉宰高表兄风雨连明遂谒朱祭酒祠即事赋 其一","f":"七言绝句","c":["薝卜风清醉骑香，满身花影踏斜阳。","行花尽处山围郭，又听松风吹客裳。"]},{"t":"以使事过成都讫事而归虞万州成都尉高表兄拉访灵泉宰高表兄风雨连明遂谒朱祭酒祠即事赋 其四","f":"七言绝句","c":["天运无穷成变化，水流不息作江淮。","须知瞪处非无事，莫着仙人旧草鞋。"]},{"t":"元夕卜油溪故事 其一","f":"七言绝句","c":["不随洛俗占灯影，不学荆人问紫姑。","卖得薪来卜油去，丰年还似去年无。"]},{"t":"王常博寄示沌路七诗李肩吾用韵为予寿因次韵 其四","f":"七言绝句","c":["竹外蒲牢叩晓鲸，玉珂金钥恍心惊。","断章韩愈赊七字，臣罪当诛王圣明。"]},{"t":"王常博寄示沌路七诗李肩吾用韵为予寿因次韵 其六","f":"七言绝句","c":["湓浦猿哀杜宇啼，琵琶弹泪送人归。","谁言苏白名相似，试看风骚赤壁矶。"]},{"t":"王常博寄示沌路七诗李肩吾用韵为予寿因次韵 其七","f":"七言绝句","c":["来时荦荦汉三明，浦雪江风尔许情。","今度王郎隔湘水，梦馀环佩玉玱琤。"]},{"t":"王常博寄示沌路七诗李肩吾用韵为予寿因次韵 其五","f":"七言绝句","c":["兄弟亲知各异方，仆夫痡困马玄黄。","惟吾臭味李夫子，不为无人不肯芳。"]},{"t":"王常博寄示沌路七诗李肩吾用韵为予寿因次韵 其二","f":"七言绝句","c":["洞烟溪月晚来村，白酒青鱼旋捭豚。","纳纳乾坤元许阔，何须头上自安盆。"]},{"t":"长女生日 其三","f":"七言绝句","c":["两地耶娘正健强，门楣况是得安郎。","七年重会非容易，且为新阳釂一觞。"]},{"t":"长女生日 其一","f":"七言绝句","c":["相逢犹记度潇湘，旋理衿缨旋理装。","婿见舅姑才识面，明朝马首上渠阳。"]},{"t":"长女生日 其二","f":"七言绝句","c":["蜑烟蛮雨锁穷荒，寇焰兵氛返故乡。","谁信梦回人似旧，青衣綵服俨成行。"]},{"t":"丙申携客自康王观东北行十里观谷帘泉 其一","f":"七言绝句","c":["正喜昔闻今见之，泉称第一更何疑。","此心好乐先为主，但见忠谋皆我欺。"]},{"t":"丙申携客自康王观东北行十里观谷帘泉 其二","f":"七言绝句","c":["笋将轧轧度岩隈，乱涧穿空去复回。","方识人间真毁誉，只缘亲到地头来。"]},{"t":"四月癸巳发浔阳馆过濂溪饭于杏溪愒清虚庵宿太平宫 其一","f":"七言绝句","c":["旌旗阴里盛传呼，春梦才醒一事无。","草草山肴话朋友，依然白鹤故时吾。"]},{"t":"四月癸巳发浔阳馆过濂溪饭于杏溪愒清虚庵宿太平宫 其四","f":"七言绝句","c":["步自清虚过上宫，千言万论总谈空。","拟将一语随人后，尝与心谋不肯同。"]},{"t":"四月癸巳发浔阳馆过濂溪饭于杏溪愒清虚庵宿太平宫 其二","f":"七言绝句","c":["多少濂溪生并时，两程夫子咏而归。","须知宇宙何曾隐，鱼自川游鸟自飞。"]},{"t":"四月癸巳发浔阳馆过濂溪饭于杏溪愒清虚庵宿太平宫 其五","f":"七言绝句","c":["又过前溪访梵宫，人言此与老庄同。","是同是异谁知得，拟问山前无极翁。"]},{"t":"四月癸巳发浔阳馆过濂溪饭于杏溪愒清虚庵宿太平宫 其三","f":"七言绝句","c":["欲识真人千古心，疗饥独有杏成林。","岂无世上閒桃李，要使人从实行寻。"]},{"t":"正月九日川上之游杨季穆以酬唱见寄走笔次韵","f":"七言绝句","c":["雨中未放笑眉开，独守空斋著玉杯。","观水功夫随处见，逝川意思即心来。"]},{"t":"用大礼杨少卿韵题冯君山庄图 其一","f":"七言绝句","c":["摩挲潘叟跨驴图，便拟移家向此居。","素富素贫随处乐，世间何地不嵩庐。"]},{"t":"用大礼杨少卿韵题冯君山庄图 其二","f":"七言绝句","c":["入山佳趣已成无，何事犹驰门外车。","书里一丁总忧患，人间六甲有孤虚。"]},{"t":"用黄侍郎韵题宇文发运瑞萱亭 其二","f":"七言绝句","c":["花开鄂鄂自相亲，枝叶根心一气春。","认得个中真血脉，孝慈天分匪由人。"]},{"t":"用黄侍郎韵题宇文发运瑞萱亭 其一","f":"七言绝句","c":["春风拍拍寿觞前，人有何忧树尔萱。","老眼未忘儿女爱，花随人意瑞家园。"]},{"t":"再用韵 其二","f":"七言绝句","c":["晓看红日上霜威，夜按苍龙运九畿。","独抱孤衷竟谁识，前山阴敛又扬挥。"]},{"t":"再用韵 其一","f":"七言绝句","c":["规摹广大理精微，天末行云鉴里飞。","莫把空言看简册，更知实理在宫闱。"]},{"t":"再用韵 其三","f":"七言绝句","c":["才资如子世应稀，自喜寒门女有归。","我被词华几陷溺，相期努力践朝晖。"]},{"t":"再用韵 其四","f":"七言绝句","c":["春风袨服驾雕几，四壮騑騑得所依。","逢快意时须缓辔，世间平地几摩围。"]},{"t":"再和招鹤 其一","f":"七言绝句","c":["仰看翔翮俯游鳞，物意容容各自春。","遥想沧江五君子，长身玉立伴閒人。"]},{"t":"再和招鹤 其四","f":"七言绝句","c":["蓬莱云近绮疏明，鹤砌分茶午梦晴。","何似林间看不足，并呼鸥鹭狎齐盟。"]},{"t":"再和招鹤 其二","f":"七言绝句","c":["声色于渠何有哉，银潢刷羽雪皑皑。","天边亦是閒游耳，争向人间问去来。"]},{"t":"再和招鹤 其三","f":"七言绝句","c":["苍苔散啄旁清江，被服委蛇未肯忙。","清唳九皋天听在，也知雅意笑鹈梁。"]},{"t":"再和前韵答赋 其五","f":"七言绝句","c":["一声凤咮朝阳里，慰我鸡鸣风雨思。","藐藐大钧那可问，有才动与厄相期。"]},{"t":"再和前韵答赋 其四","f":"七言绝句","c":["别来满眼簿书尘，想像湖边玉立身。","文阵时传骚将令，愁城不倩酒兵巡。"]},{"t":"再和前韵答赋 其三","f":"七言绝句","c":["甫田之田骄骄莠，大国之郊濯濯山。","养且难成摧则折，宁居材与不材间。"]},{"t":"再和前韵答赋 其二","f":"七言绝句","c":["秋到山川自童涸，春回草木又勾尖。","阴机尽处雷居地，月魄生时日在崦。"]},{"t":"再和前韵答赋 其一","f":"七言绝句","c":["群蜻海上迎机舞，双雁天边避弋飞。","荦荦此心天与识，滔滔斯世我谁归。"]},{"t":"后殿侍立 其三","f":"七言绝句","c":["奏事臣寮下玉阶，舍人承旨殿东来。","一声门外无公事，皇帝还宫侍卫回。"]},{"t":"后殿侍立 其二","f":"七言绝句","c":["须臾陛卫俨成行，禁跸声声辇出房。","靴笏趋陪西府拜，却更丝履立东厢。"]},{"t":"后殿侍立 其一","f":"七言绝句","c":["禁城鼓铎晓逢逢，风满衣裾靴满霜。","守得门开骑马入，又同承旨步脩廊。"]},{"t":"次李参政所和五绝句韵因以为寿 其四","f":"七言绝句","c":["天地之心万物灵，世间难得是人身。","面前放过知何限，好与光明做一巡。"]},{"t":"次李参政所和五绝句韵因以为寿 其五","f":"七言绝句","c":["天如有定开平治，宁患无人安子思。","到出手时须卓卓，逢开口处莫期期。"]},{"t":"次李参政所和五绝句韵因以为寿 其三","f":"七言绝句","c":["漠漠烟尘连北道，幽幽草树蔽南山。","照人明月长无寐，绕遍清风五百间。"]},{"t":"次李参政所和五绝句韵因以为寿 其一","f":"七言绝句","c":["竹外皋禽相与和，湖边沙雁自由飞。","美人醉踏梅花月，笑领明年春事归。"]},{"t":"次李参政所和五绝句韵因以为寿 其二","f":"七言绝句","c":["过眼浮云齐剑吷，会心真趣付炉尖。","羲皇弭节前余路，日景方中未迫崦。"]},{"t":"次李肩吾送安恕父回长沙韵 其三","f":"七言绝句","c":["匆匆郎马度烟霏，又指夕阳舂处归。","晚岁唯馀李夫子，夜窗书纸教玄晖。"]},{"t":"题陈肤仲真希元诗卷赠萧道士萧善为诗亦解鼓琴 其一","f":"七言绝句","c":["手撇飞鸢上五溪，两牛腰大送行诗。","犹嫌言语无多子，古锦奚囊长自随。"]},{"t":"题陈肤仲真希元诗卷赠萧道士萧善为诗亦解鼓琴 其二","f":"七言绝句","c":["吾庐几研半生尘，朋友相邀问保邻。","旅进群咻浑易事，邻家老子是何人。"]},{"t":"题陈肤仲真希元诗卷赠萧道士萧善为诗亦解鼓琴 其三","f":"七言绝句","c":["是间正位至虚灵，都把精神逐外明。","劝子抱琴归旧隐，乱云深处认真情。"]},{"t":"次韵丁制置远迎三绝 其三","f":"七言绝句","c":["溪瘴蛮烟隔市朝，十年山径长蒿茅。","好风吹送知时雨，生意洋洋大国郊。"]},{"t":"次韵丁制置远迎三绝 其二","f":"七言绝句","c":["乔松挺挺百年期，霜雪无端顿系之。","一点阳和消不断，春风又长岁寒枝。"]},{"t":"次韵丁制置远迎三绝 其一","f":"七言绝句","c":["锦里论交三十年，浮筠大玉透中边。","投荒已作无期别，梦觉依然堕我前。"]},{"t":"次韵王茶马海棠四绝 其一","f":"七言绝句","c":["一春风雨乱书堆，挂口林閒未放开。","浩荡和风褰客袂，来看大树簇池台。"]},{"t":"次韵王茶马海棠四绝 其三 王氏花屋海棠","f":"七言绝句","c":["宅在道傍如宝坊，一奁明玉飏新妆。","当年共赏人何在，万里相思梦寐香。"]},{"t":"次韵王茶马海棠四绝 其二 清淑堂海棠","f":"七言绝句","c":["善识花人尽倚阑，不将荣悴等閒看。","繁华夺目春如醉，独肯怀人问考槃。"]},{"t":"次韵王茶马海棠四绝 其四 燕王宫","f":"七言绝句","c":["二十四番花信风，川原无处著繁红。","逢人谩说燕宫旧，废址荒营暝霭空。"]},{"t":"次韵史少庄竹醉日移竹 其三","f":"七言绝句","c":["平生自许岁寒操，醉日移来三十丁。","底事此君亦移转，连明风雨唤教醒。"]},{"t":"次韵史少庄竹醉日移竹 其二","f":"七言绝句","c":["清如杜叟日卓午，直似姜公诗作丁。","冰雪容颜俨相值，霸陵醉尉也须醒。"]},{"t":"次韵史少庄竹醉日移竹 其四","f":"七言绝句","c":["猩屐常为醉魂役，骊珠适与睡时丁。","外物移人每如此，人心可使不长醒。"]},{"t":"次韵外舅杨崇庆以诗相招 其二","f":"七言绝句","c":["去年湖上看花时，拍槛呼鱼酌酒卮。","鱼计主人已非昔，犹惊故处上钩迟。"]},{"t":"次韵张太博见贻 其一","f":"七言绝句","c":["门前车马尘滔滔，试问有谁閒似我。","夜灯照出千古心，晓窗掣破重玄锁。"]},{"t":"次韵张太博见贻 其二","f":"七言绝句","c":["别后几如隔世人，閒中认得当年我。","清风应傍笑谭来，明月不随门户锁。"]},{"t":"次韵李参政龙鹤山庐 其四","f":"五言绝句","c":["世事从头数，时机触眼奇。","山灵莫留客，大厦要人枝。"]},{"t":"次韵李参政龙鹤山庐 其二","f":"五言绝句","c":["天公富万有，秋事不曾贫。","静阅岁时信，动观天地仁。"]},{"t":"次韵李参政龙鹤山庐 其一","f":"五言绝句","c":["山色醉痕边，溪声客枕前。","山溪元自旧，人已别经年。"]},{"t":"次韵李参政和薛秘书诗见寄 其三","f":"七言绝句","c":["行有尚时观习坎，不终止处认兼山。","止中自有流行好，不在从违用舍间。"]},{"t":"次韵李参政和薛秘书诗见寄 其五","f":"七言绝句","c":["书来寄我薛公诗，磊落襟期尉我思。","所谓伊人在空谷，公侯逸豫镇无期。"]},{"t":"次韵李参政和薛秘书诗见寄 其一","f":"七言绝句","c":["寒城眺晚牛羊下，翠荡涵秋鹳鹤飞。","风雨灯前话畴昔，应怀坡颍不成归。"]},{"t":"次韵李参政和薛秘书诗见寄 其二","f":"七言绝句","c":["扶木之阴三万丈，晓光绝出众山尖。","分明大路平如掌，朝发昆崙夕至崦。"]},{"t":"次韵李参政和薛秘书诗见寄 其四","f":"七言绝句","c":["将相时来应不免，人生难得自由身。","及今且续宋一艺，莫逐虫鱼注李巡。"]},{"t":"次韵李参政秋怀十绝 其二","f":"七言绝句","c":["稚金老火战重围，京洛缁尘点客衣。","输却东园南阁老，水花阑槛夕阳稀。"]},{"t":"次韵李参政秋怀十绝 其五","f":"七言绝句","c":["月华如水恰中庭，乌鹊枝头栖复惊。","晚暑三亭随雨过，秋声一半在虫鸣。"]},{"t":"次韵李参政秋怀十绝 其一","f":"七言绝句","c":["怒涛撞击吼笼铜，惊倒江边百岁翁。","西望阴霾犹未定，火云偏在五云东。"]},{"t":"次韵李参政秋怀十绝 其三","f":"七言绝句","c":["坱圠群灵付大钧，人生于世本何营。","浩然中夜存存气，不藉西风梦亦清。"]},{"t":"次韵李参政秋怀十绝 其六","f":"七言绝句","c":["怒雷噀雨吹尘沙，樛枝草树纷笼加。","可怜荷屋风不定，但有白红三数花。"]},{"t":"次韵李参政秋怀十绝 其四","f":"七言绝句","c":["书棚尚有送春诗，又见秋风满范围。","夜雨床头多酿酒，天边一舸有人归。"]},{"t":"次韵李参政赋蟆颐新堰 其三","f":"七言绝句","c":["八表云昏气候偏，秋霖成泽市乘船。","平舟老子閒无事，看尽熙丰祐圣年。"]},{"t":"次韵李参政赋蟆颐新堰 其二","f":"七言绝句","c":["夏秋雨集浍沟盈，雨过江空洲渚生。","事到无根元易涸，要将心地作池城。"]},{"t":"次韵李参政赋蟆颐新堰 其一","f":"七言绝句","c":["蟆颐江上静无涛，永逸功夫在一劳。","昨晚秋风原上看，长腰粳米荐琴高。"]},{"t":"次韵李彭州乞鹤于虞万州 其三","f":"七言绝句","c":["宾朋满座酒如江，雪月风花应接忙。","揽尽山林閒富贵，沧江公子太彊梁。"]},{"t":"次韵李彭州乞鹤于虞万州 其四","f":"七言绝句","c":["江头夜钓雨连明，可是渔翁太不情。","白鹤纵违华表约，黄鸡应念越人盟。"]},{"t":"次韵李彭州乞鹤于虞万州 其二","f":"七言绝句","c":["沧江羽客亦悠哉，水畔梅边雪斗皑。","白鹤山头曾有约，至今华表望归来。"]},{"t":"次韵李彭州访山居三绝 其三","f":"七言绝句","c":["不须更草北山文，归去开关扫白云。","兴未尽时仍重访，我非辟世可同群。"]},{"t":"次韵李彭州访山居三绝 其一","f":"七言绝句","c":["只嫌湫隘近城居，无着名山万卷书。","不道八荒皆我宇，独于此处认吾庐。"]},{"t":"次韵杨尚书立春 其一","f":"七言绝句","c":["帽屋钗梁剪綵新，谁知井底及池濒。","只从阳月方中日，已作明年第一春。"]},{"t":"次韵杨尚书立春 其二","f":"七言绝句","c":["行玉盘中惊杜老，扣窗声里唤祈宾。","扶持大道须公等，正恐乡车未可巾。"]},{"t":"次韵黄侍郎沧江海棠六绝 其三","f":"七言绝句","c":["为怜一片晓云红，未放千丝暮雨浓。","调燮阴阳贤岳牧，满川花意得舂容。"]},{"t":"次韵黄侍郎沧江海棠六绝 其六","f":"七言绝句","c":["指麾红紫思无滨，抵当丹青笔有神。","百树花閒一编易，主人意韵镇长新。"]},{"t":"次韵黄侍郎沧江海棠六绝 其四","f":"七言绝句","c":["惯踏郊原浩荡春，重来春与物俱新。","渠虽自有生生意，把握天机是主人。"]},{"t":"次韵黄侍郎沧江海棠六绝 其五","f":"七言绝句","c":["帝恐嘉花不易成，好风迟日故来承。","繁红错眩渔人眼，不识沧江有武陵。"]},{"t":"次韵黄侍郎沧江海棠六绝 其二","f":"七言绝句","c":["沙暖花香弄午晴，苦撩诗思浩难禁。","偷閒不办追年少，只有春风会此心。"]},{"t":"次韵黄侍郎沧江海棠六绝 其一","f":"七言绝句","c":["妙处东皇可得知，溶溶生意不停机。","雨寒日暴浑无赖，凭仗阳和为解围。"]},{"t":"次韵黄侍郎海棠花下怯黄昏七绝 其三","f":"五言绝句","c":["唐人春深题，用韵工车斜。","逐逐语言去，谁欤真识花。"]},{"t":"次韵黄侍郎海棠花下怯黄昏七绝 其四","f":"五言绝句","c":["临川数落花，康节爱花谢。","若作荣悴观，此特花之下。"]},{"t":"次韵黄侍郎海棠花下怯黄昏七绝 其二","f":"五言绝句","c":["曾访郊原春，静观烟雨妆。","因物得良晤，谅非昔如棠。"]},{"t":"次韵虞永康十月海棠 其一","f":"七言绝句","c":["冷淡庭梅俨玉颜，孤高翠竹耸脩鬟。","如何富贵天然质，犹欲寻盟二友间。"]},{"t":"次韵虞永康十月海棠 其二","f":"七言绝句","c":["春意何曾间四时，芸芸静处锦成帷。","非关造化呈新巧，钧播无心自不知。"]},{"t":"次韵虞退夫除夕七绝句 其六","f":"七言绝句","c":["人道渠阳尔崄艰，崄艰在彼我何关。","却从楚泽宽平后，彫尽从前镜里颜。"]},{"t":"次韵虞退夫除夕七绝句 其五","f":"七言绝句","c":["长叹熙丰祐圣年，偏轻偏重几番船。","谁能装载亭匀了，多著男儿尽力牵。"]},{"t":"次韵虞退夫除夕七绝句 其七","f":"七言绝句","c":["虞倩思亲感岁年，归心巫峡暮云前。","乖逢逝止那能料，静倚閒云看大川。"]},{"t":"次韵虞退夫除夕七绝句 其一","f":"七言绝句","c":["蜀人谁不望西还，何事天公独我悭。","两度来逢单阏岁，腥风血雨满人间。"]},{"t":"次韵虞退夫除夕七绝句 其一","f":"七言绝句","c":["太极光阴不计年，圣贤千古此周旋。","九夷自陋吾何与，长在回瓢点瑟边。"]},{"t":"次韵虞退夫除夕七绝句 其二","f":"七言绝句","c":["谁驱斗柄向东迁，渐喜新年胜故年。","岁纬移躔东井外，狼星敛角左参边。"]},{"t":"次韵虞退夫除夕七绝句 其四","f":"七言绝句","c":["云外衔山日半环，传杯共惜片云欢。","莫疑来日是来岁，万古光阴只么看。"]},{"t":"次韵虞退夫除夕七绝句 其二","f":"七言绝句","c":["从渠满腹贮千年，遮莫挥毫动百篇。","入到圣门无一事，东西日月自行天。"]},{"t":"次韵虞退夫除夕七绝句 其三","f":"七言绝句","c":["是滔滔者竟谁归，有酒盈卮不暇挥。","待挽长江洗兵马，尽还草木旧晶晖。"]},{"t":"次韵虞退夫除夕七绝句 其四","f":"七言绝句","c":["已是秋阴误有年，泰交倏变震乘乾。","阿香夜夜惊春梦，推出新悲上鬓边。"]},{"t":"次韵虞退夫除夕七绝句 其六","f":"七言绝句","c":["又叹崇宁宣政年，无端亡虏误开边。","谁能为我惩前辙，早挈江山入舜甄。"]},{"t":"次韵虞退夫除夕七绝句 其七","f":"七言绝句","c":["明朝同上四贤山，要与群英尽日还。","认取钩深堂上意，春风曳曳鸟关关。"]},{"t":"次韵虞退夫除夕七绝句 其三","f":"七言绝句","c":["将军元自敬延年，明主何曾弃浩然。","自分康时了无策，故山多少未芸田。"]},{"t":"次韵虞退夫除夕七绝句 其五","f":"七言绝句","c":["几度将心安处安，有时中夜起长叹。","年来识得安心法，否泰元从随蛊看。"]},{"t":"次韵谯仲甫致政闻南迁见寄 其一","f":"七言绝句","c":["梦馀不省卧山城，犹记封章入殿荣。","蜑雨蛮风唤苏醒，谯南残点一声声。"]},{"t":"次韵谯仲甫致政闻南迁见寄 其二","f":"七言绝句","c":["群蜚逐食傍人鸣，暝霭蒸山浓欲倾。","世事满头归未得，片心直向日边明。"]},{"t":"次韵德先步月答所问语 其二","f":"五言绝句","c":["夜景湛虚明，浩然无与京。","如今苏氏妇，但指圣人清。"]},{"t":"次韵德先步月答所问语 其一","f":"五言绝句","c":["三更端正月，皎亮直瑶京。","客问心之体，无言对太清。"]},{"t":"次韵德先步月答所问语 其三","f":"五言绝句","c":["霁月光湓浦，吟风归洛京。","迥无纤霭翳，千古识真清。"]},{"t":"西叔兄生日 其一","f":"七言绝句","c":["从渠冷煖广文君，发越春和别有根。","乐意融融兄及弟，庆流衮衮子生孙。"]},{"t":"西叔兄生日 其二","f":"七言绝句","c":["只把农功作己忧，不将岁事与天谋。","官修事举文书静，一室高眠粥似稠。"]},{"t":"西叔兄生日 其三","f":"七言绝句","c":["上寿班齐日未升，风廊露幕立公卿。","亲闻商略西南彦，争说高家好弟兄。"]},{"t":"西叔兄生日 其四","f":"七言绝句","c":["花底班行锦样明，中閒宁少紫青人。","更无入诵成都赋，拟抗声来问大钧。"]},{"t":"讲筵侍立 其三","f":"七言绝句","c":["御前亲赐密云龙，讲罢分行帝在中。","起揖坐尝还再拜，侍臣趋出辇还宫。"]},{"t":"讲筵侍立 其二","f":"七言绝句","c":["须臾讲殿报班齐，拜罢东升一半西。","两序公卿皆赐坐，史臣讲读右阶隮。"]},{"t":"讲筵侍立 其一","f":"七言绝句","c":["晨趋东朵侍天颜，奏事班回帝辇还。","才向内门需少选，诸珰又趣讲筵班。"]},{"t":"李参政生日 其六","f":"七言绝句","c":["分付诸儿自致身，朝阳阁上看长春。","梅边认得真消息，往古来今一屈伸。"]},{"t":"李参政生日 其三","f":"七言绝句","c":["八十蹁跹老阿兄，一窗风雨伴双清。","武昌近日音书少，时听湖边过雁声。"]},{"t":"李参政生日 其五","f":"七言绝句","c":["梅艳凌霜带雪馀，铅华洗尽玉生肤。","东方千骑推人去，聊折春风寄雁湖。"]},{"t":"李参政生日 其五","f":"七言绝句","c":["剺面花门未果驯，夏人兵马薄熙秦。","谁将鞭策驱时运，十数年间日日新。"]},{"t":"李参政生日 其六","f":"七言绝句","c":["绝嗤梁梦误金瓯，又叹祁征困木牛。","只藉人才作元气，闻公安健百无忧。"]},{"t":"李参政生日 其三","f":"七言绝句","c":["才记官来早去官，行人惊说路艰难。","行藏用舍何关我，时把尼渊出处看。"]},{"t":"李参政生日 其四","f":"七言绝句","c":["历尽玄枵十二辰，饱看三十六宫春。","才喷一霎挂龙雨，又卷云霓还翠旻。"]},{"t":"李参政生日 其四","f":"七言绝句","c":["泻出清明醉眼醒，都人弹指祝前星。","凭谁提起源头话，治国齐家要六经。"]},{"t":"李参政约至井监偶得三绝 其一","f":"七言绝句","c":["忽闻车马下天来，拥术阗衢拨不开。","六十七年无此客，灶前老隶亦惊猜。"]},{"t":"李参政约至井监偶得三绝 其二","f":"七言绝句","c":["不乘轞轞上公车，轧轧肩舆两仆夫。","世道险夷随所遇，车中只是旧时吾。"]},{"t":"李参政约至井监偶得三绝 其三","f":"七言绝句","c":["溪边鹄白芦花瘦，山下鹅黄稻实肥。","更得天公晴十日，今年穑事庶乎几。"]},{"t":"李参政折赠黄香梅与八咏俱至用韵以谢 其三","f":"七言绝句","c":["露拂蔷薇不太深，春风庭院晚阴阴。","来迟未入黄昏句，谁唤钱塘人姓林。"]},{"t":"李参政折赠黄香梅与八咏俱至用韵以谢 其六","f":"七言绝句","c":["玄天黄露真颜色，金步摇中颤舞娃。","更倩南窗书奶味，不妨来伴太常斋。"]},{"t":"李参政折赠黄香梅与八咏俱至用韵以谢 其八","f":"七言绝句","c":["诗翁曾住玉皇家，刚与梅花定等差。","染上鞠衣宫样浅，练裙缟帨觉无华。"]},{"t":"李参政折赠黄香梅与八咏俱至用韵以谢 其二","f":"七言绝句","c":["犀镇帘帷风绰开，当庭恰似剪花回。","眉间一点看浑似，笑领江南春信来。"]},{"t":"李参政折赠黄香梅与八咏俱至用韵以谢 其五","f":"七言绝句","c":["冰魂玉骨一枝春，风格南昌旧子真。","谁幻神仙黄白术，时装近日太尖新。"]},{"t":"李参政折赠黄香梅与八咏俱至用韵以谢 其七","f":"七言绝句","c":["和羹心事岁寒姿，若第风标舍更谁。","谩道色轻花更艳，几成涂抹水边枝。"]},{"t":"李参政折赠黄香梅与八咏俱至用韵以谢 其四","f":"七言绝句","c":["入眼风光似世情，金裳玉质转分明。","额黄十二谁分似，疑是仙人成智琼。"]},{"t":"李参政折赠黄香梅与八咏俱至用韵以谢 其一","f":"七言绝句","c":["黄云冉冉晓苍苍，閒倚平湖只自香。","较似寒枝虽未至，依然风韵挟冰霜。"]},{"t":"李提刑李参政再和招鹤诗再用韵以谢 其三","f":"七言绝句","c":["须眉皓白何为者，未出山时举世忙。","若使当时容易致，等閒鹙鹤混鱼梁。"]},{"t":"李提刑李参政再和招鹤诗再用韵以谢 其四","f":"七言绝句","c":["弟兄孙子总英明，玉雪成围眩昼晴。","寄语茅山何道士，不须苦共鹤寻盟。"]},{"t":"李提刑李参政再和招鹤诗再用韵以谢 其二","f":"七言绝句","c":["锦江相去几何哉，未见窗前落雪皑。","声气同时无间断，有时夜半掠江来。"]},{"t":"李微之闻其弟贯之西归以诗迓之刘左史和韵属余同赋 其一","f":"七言绝句","c":["室中万象镇宽閒，舒卷风烟入凤山。","俯听候虫坏户去，仰看倦雁绝云还。"]},{"t":"李微之闻其弟贯之西归以诗迓之刘左史和韵属余同赋 其六","f":"七言绝句","c":["曩与刘公同一邦，如今背我去堂堂。","京师尊贵在朝者，为问谁能踰阿章。"]},{"t":"李微之闻其弟贯之西归以诗迓之刘左史和韵属余同赋 其二","f":"七言绝句","c":["只期玉女是用谏，肯为金夫不有躬。","想见江南两肤使，天涯憔悴鬓成翁。"]},{"t":"李微之闻其弟贯之西归以诗迓之刘左史和韵属余同赋 其五","f":"七言绝句","c":["滔滔斯世我谁归，置散投閒分亦宜。","乾鹊颇惊仁鸟害，坚冰已向履霜知。"]},{"t":"李微之闻其弟贯之西归以诗迓之刘左史和韵属余同赋 其四","f":"七言绝句","c":["公卿奏疏谩琅琅，谁刃楼兰槛鬼章。","巢燕豫忧江上北，幕乌未到岘之阳。"]},{"t":"李微之闻其弟贯之西归以诗迓之刘左史和韵属余同赋 其三","f":"七言绝句","c":["行李营营遍八荒，曲车炙骑趁春忙。","莞然独笑无人管，寒蕙墙东蜀海棠。"]},{"t":"杨仲博生日 其一","f":"七言绝句","c":["平塍雨足蟹鱼肥，远水涵空鹳鹤飞。","相对不知身是客，两家儿女綵成围。"]},{"t":"杨仲博生日 其二","f":"七言绝句","c":["玉粹金浑好弟兄，向来驰誉鬓双青。","世间贤美宁常有，百岁三亭过一亭。"]},{"t":"杨仲博生日 其三","f":"七言绝句","c":["任教寒畯着先鞭，尽使权豪紊选班。","纵诮我迂嗤我矫，个中所负重于山。"]},{"t":"杨尚书和晴字韵诗适趋部宿再韵谢之 其二","f":"七言绝句","c":["冬令阴阴我独晴，世间寒暑本思成。","玉珂金钥声中睡，无限山林入耳声。"]},{"t":"杨尚书和晴字韵诗适趋部宿再韵谢之 其一","f":"七言绝句","c":["静将躯干验阴晴，风雪中閒玉汝成。","襆被直趋郎省直，更无剌剌耳边声。"]},{"t":"泸帅曹太博生日四首 其四","f":"七言绝句","c":["荦荦圣门心事长，悠悠客路鬓毛苍。","东南人物寥寥甚，扶植斯文我所望。"]},{"t":"泸帅曹太博生日四首 其三","f":"七言绝句","c":["十年更瑟不曾调，百载张弓未肯弨。","随事提撕民受赐，宁论外服与王朝。"]},{"t":"泸帅曹太博生日四首 其二","f":"七言绝句","c":["天马无踪运四时，试将六十四年推。","后天八八方来数，加倍无穷自此基。"]},{"t":"泸帅曹太博生日四首 其一","f":"七言绝句","c":["荔香摇艇下泸川，自别君侯十八年。","尉我调饥刻为岁，争如两日往南田。"]},{"t":"和王太博斋宫梦中绝句","f":"五言绝句","c":["晴轻风慭冻，寒重日生烟。","谩道中和节，天颜正愀然。"]},{"t":"和史少庄登山韵三首 其三","f":"五言绝句","c":["毋谓支山险，此山能几何。","崎嵚十年梦，知历几蹉跎。"]},{"t":"和史少庄登山韵三首 其二","f":"五言绝句","c":["田间逢醉尉，人道误谁何。","世路日杲杲，冥行宜见呵。"]},{"t":"和史少庄登山韵三首 其一","f":"五言绝句","c":["剩喜向前坡，人情奈怯何。","君今高著步，直与陟嶒峨。"]},{"t":"和别驾喜雨四绝 其四","f":"七言绝句","c":["山北山南遍插秧，天时较似去年彊。","从今无事閒风月，分作屏星一半凉。"]},{"t":"和别驾喜雨四绝 其三","f":"七言绝句","c":["尔游尔衍与天同，无处无时不感通。","芸鼓渐稀铃索静，茶烟摇飏晚香中。"]},{"t":"和别驾喜雨四绝 其二","f":"七言绝句","c":["夏畦活活翠芊绵，起视微云尚黯然。","底事化工浑不费，笑余何敢更贪天。"]},{"t":"和别驾喜雨四绝 其一","f":"七言绝句","c":["四山镕日泻黄金，谁载亭皋一尺霖。","息处生机无间断，划然有顷验天心。"]},{"t":"和李校书沐川三绝 其一","f":"七言绝句","c":["静看青山簇髻鬟，动观碧水漱潺湲。","若教此景来酆鄗，争夺应成触与蛮。"]},{"t":"和李校书沐川三绝 其三","f":"七言绝句","c":["玉节行边春正浓，边头壮士簸旗红。","何当平贼携诸吏，径上高寒剪剪风。"]},{"t":"和虞永康梅花十绝句 其一","f":"七言绝句","c":["蓬蒿已逐晓霜眠，玉立孤标汉绮园。","月澹风轻云欲压，精神千古对羲轩。"]},{"t":"和虞永康梅花十绝句 其三","f":"七言绝句","c":["天然标韵耸高寒，觌面松筠取友端。","直截语人人不解，等閒只作好花看。"]},{"t":"和虞永康梅花十绝句 其七","f":"七言绝句","c":["沧江卜室数年间，畚筑栽培仅息肩。","生色油然已如此，个中自有不须禅。"]},{"t":"和虞永康梅花十绝句 其十","f":"七言绝句","c":["世间无物可谈空，开落荣枯实理同。","百树好花一编易，主人立处俨当中。"]},{"t":"和虞永康梅花十绝句 其九","f":"七言绝句","c":["幽光冷艳照前坡，花下期君不啻过。","木落江空岁年晚，此诗朋友望西河。"]},{"t":"和虞永康梅花十绝句 其五","f":"七言绝句","c":["轻寒玉蓓试新妆，已识微酸一点黄。","生意溶溶无间断，何须闻笛为沾裳。"]},{"t":"和虞永康梅花十绝句 其八","f":"七言绝句","c":["树花禽语恰逢时，真意相关两绝奇。","独坐黄昏先得月，呼僮点笔和梅诗。"]},{"t":"和虞永康梅花十绝句 其六","f":"七言绝句","c":["重阴浩瀚渺无滨，草木摧残见本真。","谁识江南一枝信，明年春事正催人。"]},{"t":"和虞永康梅花十绝句 其二","f":"七言绝句","c":["不随妖艳竞花期，叶落惟存老树枝。","林下水边时一见，相逢颇恨几年迟。"]},{"t":"和虞永康梅花十绝句 其四","f":"七言绝句","c":["远山云抹半横簪，野色昏明水浅深。","庭外沉沉人不到，凛然玉雪对疏林。"]},{"t":"和虞退夫见贻生日诗韵 其四","f":"七言绝句","c":["虎豹当关路险艰，家人占鹊望予还。","四方蹙蹙还何许，家在西南山外山。"]},{"t":"和虞退夫见贻生日诗韵 其三","f":"七言绝句","c":["九十九峰江上山，乾坤尔阔我中间。","此心顿著秋豪愧，久矣颜衰鬓发斑。"]},{"t":"和虞退夫见贻生日诗韵 其五","f":"七言绝句","c":["范蒋诸贤友义申，肩吾见说倍精神。","年来人物寥寥甚，更忆浦城人姓真。"]},{"t":"和虞退夫见贻生日诗韵 其一","f":"七言绝句","c":["夫容布叶乱田田，尚忆前年对二贤。","今度观亭人独立，一江风月意谁传。"]},{"t":"和虞退夫韵 其二","f":"七言绝句","c":["牛女河边两夹持，前瞻箕斗后虚危。","经星不动元如此，自是人閒空好奇。"]},{"t":"和虞退夫韵 其一","f":"七言绝句","c":["醵酒成欢似旅酬，偶然解后得英游。","却因乐极生良感，今夜蟾光照几州。"]},{"t":"和靖州判官陈子从山水图十韵 松径晚步","f":"五言绝句","c":["松柏不受彫，此亦易知耳。","须看竹有筠，与松相表里。"]},{"t":"和靖州判官陈子从山水图十韵 星湾晚酌","f":"五言绝句","c":["士非耕钓者，而从蓑笠翁。","人生贵适志，莘渭亦时中。"]},{"t":"和靖州判官陈子从山水图十韵 雪中访友","f":"五言绝句","c":["怀人得清晤，此乐浩无期。","剡溪兴尽返，未喻伐木诗。"]},{"t":"和靖州判官陈子从山水图十韵 彭蠡归舟","f":"五言绝句","c":["外物羁絷人，无退亦无遂。","愧彼自由身，朝发夕予至。"]},{"t":"夜直玉堂 其一","f":"七言绝句","c":["金銮坡上疏开边，梦也非与三十年。","世事烟埃缘手尽，正邪二字在遗编。"]},{"t":"夜直玉堂 其二","f":"七言绝句","c":["金羁玉勒锦笼鞯，重上銮坡鬓欲宣。","自喜晨趋无愧色，更忻夜直得安眠。"]},{"t":"肩吾生日 其二","f":"七言绝句","c":["力探上下三千载，行半东西二百州。","有许豪雄都忘却，松窗棐几静中求。"]},{"t":"肩吾生日 其三","f":"七言绝句","c":["馀晦越乡别临贺，郭君出竟送荆州。","放麑心事人誇说，得似如今累岁留。"]},{"t":"肩吾生日 其一","f":"七言绝句","c":["谁遣青龙日夜流，记经星纪已降娄。","边城恰匝三寒暑，初度联翩四倡酬。"]},{"t":"肩吾生日三绝句 其一","f":"七言绝句","c":["尚记联车入界头，廉安门外麦三秋。","江山气度依前伟，简册功夫匪昔侔。"]},{"t":"肩吾生日三绝句 其三","f":"七言绝句","c":["昔人年德位俱优，淇奥宾筵苦自脩。","学至百年宁有厌，勉哉三十六春秋。"]},{"t":"肩吾生日三绝句 其二","f":"七言绝句","c":["世历嬴刘周典尽，经由孙沈古音休。","更嗟书法开元坏，不易肩吾字字求。"]},{"t":"肩吾生日以三绝为寿 其一","f":"七言绝句","c":["俗学场中蚤掉头，一窗书卷古人谋。","东西日月自明耳，皇恤人间有喘牛。"]},{"t":"肩吾生日以三绝为寿 其三","f":"七言绝句","c":["宇静昼窗长似岁，心清夏簟冷于秋。","是间消息君知得，看尽区中浪白头。"]},{"t":"肩吾生日以三绝为寿 其二","f":"七言绝句","c":["穷檐小市百年州，浅濑平沙万古流。","天运人谋镇如此，晚醺时上驿南楼。"]},{"t":"青玉峡","f":"七言绝句","c":["一派泉声万古悬，观澜叹逝意悠然。","须知大化无穷已，莫赋银河落九天。"]},{"t":"将入靖州界适值肩吾生日为诗以寿之 其一","f":"七言绝句","c":["肩吾名地古诚州，明日联车入界头。","草草三杯酌初度，恍如赤壁伴元脩。"]},{"t":"将入靖州界适值肩吾生日为诗以寿之 其三","f":"七言绝句","c":["道亨初不关穷达，身健何须问去留。","但愿王明天地泰，此生长共国同休。"]},{"t":"将入靖州界适值肩吾生日为诗以寿之 其二","f":"七言绝句","c":["滔滔今古满双鬓，纳纳乾坤归两眸。","自有江山几千载，颇曾有此主宾不。"]},{"t":"将至古渝虞宪以三绝同端午节见寄用韵为谢 其三","f":"七言绝句","c":["蓬窗暑雨气低垂，不记龙舟竞渡期。","诗卷打门惊节序，满盘角黍正累累。"]},{"t":"将至古渝虞宪以三绝同端午节见寄用韵为谢 其二","f":"七言绝句","c":["鬓边忧绪已千端，谁唤扁舟下濮干。","落日明船剑如电，勇心触拨到楼兰。"]},{"t":"将至古渝虞宪以三绝同端午节见寄用韵为谢 其一","f":"七言绝句","c":["故山朱果恰离离，翠竹青蒲护众菲。","梦里不知身造阙，閒随白鹤照江衣。"]},{"t":"将作监栽竹徐直翁清叟俾予书植贤亭三大字以诗见贻 其二","f":"七言绝句","c":["气端解使四时青，万物彫零独典刑。","严子高风扶汉鼎，包胥劲节撼秦庭。"]},{"t":"将作监栽竹徐直翁清叟俾予书植贤亭三大字以诗见贻 其一","f":"七言绝句","c":["烈日严霜恣挟持，孤标荦荦肯随时。","笑看世上閒桃李，一夕狂风失令姿。"]},{"t":"将作监栽竹徐直翁清叟俾予书植贤亭三大字以诗见贻 其三","f":"七言绝句","c":["客梦时时绕故山，梦馀砉见玉孱颜。","徐公本自无通介，自是时人醉眼斑。"]},{"t":"春社日祀事既毕轿中得三绝 其一","f":"七言绝句","c":["风雨声中听李陵，起来被服对神明。","歌钟才彻车轓动，归到谯楼恰六更。"]},{"t":"春社日祀事既毕轿中得三绝 其二","f":"七言绝句","c":["辗然冯轼受风吹，吏皂前惊雨湿衣。","岂识主人非崛强，一川生意索褰帏。"]},{"t":"春社日祀事既毕轿中得三绝 其三","f":"七言绝句","c":["阴雾冥濛慢鼓鼙，田坡勃窣误轮蹄。","居人闭户未忺起，太守车前一尺泥。"]},{"t":"昨有祷于社稷及境内山川是夕枕上闻雨 其一","f":"七言绝句","c":["郊宫方社诗攸重，川泽山林礼所崇。","古祀不修牲币废，梵铙声里纸钱风。"]},{"t":"舣舟琵琶亭次福士张元龙以诗代柬韵 其一","f":"七言绝句","c":["人生行止莫非天，万里风波一叶船。","时有宾朋慰牢落，宁论远道困行躔。"]},{"t":"舣舟琵琶亭次福士张元龙以诗代柬韵 其二","f":"七言绝句","c":["乐天未信果知天，枉为琵琶弦系船。","须识屈信常事耳，暑寒代序月移躔。"]},{"t":"赵深甫年七十有亲九十贫无以养索赋","f":"七言绝句","c":["囝思郎罢久无炊，父曰子行胡不归。","负米上堂宽带索，不妨逿地戏儿衣。"]},{"t":"送从子令宪西归 其四","f":"七言绝句","c":["自尔南来岁再周，新功培养气扬休。","且留数月须多益，归妹愆期母所忧。"]},{"t":"送从子令宪西归 其一","f":"七言绝句","c":["弟兄亲友剑南州，别思如山浩不收。","家问稀疏人迹绝，眼明从子慰羁愁。"]},{"t":"送从子令宪西归 其三","f":"七言绝句","c":["古来明戒有弦钩，伯父胡为苦好脩。","累尔南行数千里，我之自取尔何尤。"]},{"t":"送从子令宪西归 其五","f":"七言绝句","c":["古人为学戒悠悠，说命惟从务敏求。","识此味时那可已，更从来处验吾脩。"]},{"t":"送从子令宪西归 其六","f":"七言绝句","c":["弘毅规摹本末周，既难分付又难酬。","须知陋巷忧中乐，又识耕莘乐处忧。"]},{"t":"送安同知赴阙 其五","f":"七言绝句","c":["闭门睡息正齁齁，野卉蓬蓬烂不收。","只忧一夜西风急，恼乱东邻卒未休。"]},{"t":"送安同知赴阙 其四","f":"七言绝句","c":["未须多买酂侯田，且可同乘曲逆船。","昨夜皛山云作雨，东流一水径通天。"]},{"t":"送安同知赴阙 其三","f":"七言绝句","c":["当年匣剑授彬时，都在将军颐指麾。","谁者纷纷容易取，高皇约束变更为。"]},{"t":"送安同知赴阙 其二","f":"七言绝句","c":["京邑殿留司马相，东山无以我公归。","德人用舍关天运，世上巫咸妄见机。"]},{"t":"送安同知赴阙 其一","f":"七言绝句","c":["忧民白发三千丈，报国丹心十二时。","独倚长空望红日，满帘风雨燕喃呢。"]},{"t":"夏至日祀阏伯于开元宫前三日省中斋宿 其二","f":"七言绝句","c":["朱荣铅砌拱都堂，静閤明窗夹主廊。","外省诸司西侧畔，枢寮却在外东厢。"]},{"t":"夏至日祀阏伯于开元宫前三日省中斋宿 其一","f":"七言绝句","c":["书生只惯野人庐，谁识潭潭省府居。","独坐黄昏谁是伴，紫微阁上四厨书。"]},{"t":"射殿引诸班出官人拽垛子 其二","f":"七言绝句","c":["控矢张弓十作朋，射馀回首列前荣。","须臾当殿听宣授，首下尻高万岁声。"]},{"t":"射殿引诸班出官人拽垛子 其一","f":"七言绝句","c":["画帘黄幄幕前扉，侠陛浑如后殿仪。","只自起居更履后，却陪二府立多时。"]},{"t":"恭和闻喜宴赐毛自知以下御制","f":"七言律诗","c":["昭代宾贤礼意诚，镐京设席蔼儒缨。","龙飞十二周星纪，鹏运三千击水程。","云汉成章新宠渥，钧天张乐播和平。","微臣置馈申规戒，贤网虽恢用欲精。"]},{"t":"真除后谩记所见 其一","f":"七言绝句","c":["晓风鞭袖闯天关，滥缀东西两省班。","当日入趋东朵殿，番休却逐侍臣还。"]},{"t":"真除后谩记所见 其三","f":"七言绝句","c":["晨将榜子关宾閤，辇出房时已奏知。","陛对臣寮才下殿，朱衣丝履上东墀。"]},{"t":"真除后谩记所见 其二","f":"七言绝句","c":["记注愆期已隔年，濡螭夹案谩云然。","惟馀一事光千古，后殿前朝听直前。"]},{"t":"袁都官同前韵赋二诗一章问易边赋唐律二章索奏劄录本 其二","f":"七言绝句","c":["一天西雨又东晴，唤作阴晴雨不成。","朝睡着人浑未觉，鸣嘤枝上一声声。"]},{"t":"袁都官同前韵赋二诗一章问易边赋唐律二章索奏劄录本 其一","f":"七言绝句","c":["那得閒功咏雪晴，风光自解凑诗成。","须知精粗无非易，千古人心只一声。"]},{"t":"翌日约客有和者再用韵四首 其四","f":"七言绝句","c":["古来长恨难并四，今日相逢所就三。","花里宾朋皆臭味，夜凉风月更清酣。"]},{"t":"翌日约客有和者再用韵四首 其三","f":"七言绝句","c":["妙处和春莫遣知，晚尊随柳逐花移。","落花绣地春深日，翠柳筛空月上时。"]},{"t":"翌日约客有和者再用韵四首 其二","f":"七言绝句","c":["堆案文书长引睡，起来搔首乱鬅鬙。","眼明嘉卉纷纨绮，竟是脩篁耸棘矜。"]},{"t":"翌日约客有和者再用韵四首 其一","f":"七言绝句","c":["柳梢庭院杏花墙，尚记春风绕画梁。","二十四番花信尽，只馀箫鼓卖饧香。"]},{"t":"登冠山次瞻叔兄壁间旧韵 其二","f":"七言绝句","c":["又到黄昏别有天，落霞明水月衔山。","乱烟远树供诗卷，浊酒狂歌伴醉颜。"]},{"t":"登冠山次瞻叔兄壁间旧韵 其一","f":"七言绝句","c":["芦花朴朴雪连天，枫叶椮椮日满山。","似识游人非俗客，远峰呈露玉孱颜。"]},{"t":"韩少谟挽诗 其三","f":"七言绝句","c":["镜里孤鸾背影飞，庭前玉树向人稀。","尚思别我成都去，忍听虞歌薤露归。"]},{"t":"韩少谟挽诗 其二","f":"七言绝句","c":["据鞍新息困壶头，款段何如弟少游。","马革裹尸吾愿足，不然肯向死前休。"]},{"t":"韩少谟挽诗 其一","f":"七言绝句","c":["早年豪气盖区中，晚岁颓然一病翁。","负许才华竟何事，有皇上帝岂梦梦。"]},{"t":"虞退夫生日 其二","f":"七言绝句","c":["初度重逢巽上坤，庭闱应念子生孙。","好将吉语传金母，更把归音报玉昆。"]},{"t":"虞退夫生日 其二","f":"七言绝句","c":["雍公匹马立乾坤，善念熏蒸到子孙。","富贵君家馀事耳，更将此念植仍昆。"]},{"t":"题上亭驿","f":"七言绝句","c":["红锦绷盛河北贼，紫金盏酌寿王姬。","弄成晚岁琅当曲，正是三郎快活时。"]},{"t":"题归宗寺","f":"七言绝句","c":["愦愦深源与会稽，识时惟有一羲之。","千年误作能书看，谩说鹅池与墨池。"]},{"t":"题石兴宗读书岩","f":"七言绝句","c":["岩头橘树经百黄，三少不生诸老亡。","只馀石间元祐脚，谷虚尽日鸣当当。"]},{"t":"题米南宫云山挂幅","f":"七言绝句","c":["漠漠云林小小山，谁家茅屋隐松间。","石桥雨过天台远，采药仙人去未还。"]},{"t":"题余氏聚远楼","f":"七言绝句","c":["若向天机识得亲，是间看不尽青春。","须知聚远惟方寸，说与楼前望眼人。"]},{"t":"题苏文忠与邓安惠西山唱和","f":"七言绝句","c":["春风吹屧上黄冈，独倚斜阳看武昌。","城郭山川几兴废，祇留元祐姓名香。"]},{"t":"题罗年能六友堂","f":"七言绝句","c":["罗氏堂中六友图，要求纸尾数行书。","若于此味真知得，着甚言词乞与渠。"]},{"t":"题峡州三游洞 其二","f":"七言绝句","c":["可怪忠州与虢州，偶因起废得兹游。","苏欧诸老亦何德，千古联芳未肯休。"]},{"t":"题峡州三游洞 其一","f":"七言绝句","c":["洞前日日客维舟，短咏长吟汗马牛。","名迹都随形气尽，惟馀元白几人留。"]},{"t":"题赵昌父太社寄桃源何道士","f":"七言绝句","c":["八十六年彊健客，求余判断二苏诗。","年来点检室中事，问着邻家总不知。"]},{"t":"赠术士龚恢乙","f":"五言绝句","c":["龚生来过我，极意论先天。","自得环中趣，无言已十年。"]},{"t":"九月丁亥秋祀毕劳农北郊苏提干以疾不往以诗见寄因次其韵","f":"七言律诗","c":["秋尝事毕与宾游，神惠如临不敢留。","骑吹一川松露晓，踏歌千里稻云秋。","豳公堂上兕觥荐，郓使溪前经律诹。","尽日临民看不足，归从苏子静中求。"]},{"t":"二月二日遂宁北郊迎富故事","f":"七言律诗","c":["才过结柳送贫日，又见簪花迎富时。","谁为贫驱竟难逐，素为富逼岂容辞。","贫如易去人所欲，富若可求吾亦为。","里俗相传今已久，谩随人意看儿嬉。"]},{"t":"人日约李提刑李参政登蟆颐马上醉书","f":"七言律诗","c":["只从元日到人日，便觉新年胜故年。","买酒买符酬旧社，宜蚕宜麦祝新田。","般添和气开花柳，嗺送韶华入管弦。","我本田间饭牛者，偶来解后亦犁然。"]},{"t":"人日南山寺约汪宪","f":"七言律诗","c":["天开三十六宫春，又见阶蓂七叶新。","雨足剪来齐麦垄，时和看不断游轮。","记曾英簜为使客，却拥朱轓作主人。","客主何常均寄耳，系边认取本来身。"]},{"t":"八月十四日夜约客月下有赋","f":"七言律诗","c":["秋空和月卷玻瓈，清入肝脾触拨诗。","元自生来全体具，只缘见处一分亏。","俗情数日须圆候，识者先几畏满时。","千古词人谁解道，拟将今夕当佳期。"]},{"t":"八月十四夜月用旧作韵呈诸友","f":"七言律诗","c":["鬓发成宣面欲黎，逢人耻诵故年诗。","才看震象应知满，未睹乾爻已识亏。","止处光明浑在里，偶然显晦谩随时。","风光流转浑閒事，要与知心结久期。"]},{"t":"上巳日约同僚过蟆颐晚视新开横江堰","f":"七言律诗","c":["朏魄双交气候新，古今为乐属兹辰。","兰堂坐上皆豪逸，韦曲水边多丽人。","顾我未能真免俗，邀宾聊复共行春。","却因游豫思民事，检校城东白虎津。"]},{"t":"与刘左史同别杨少卿于南郊舟中用宋兵部韵","f":"七言律诗","c":["玉龙老子访仙鹤，冲佑散人归瑞乌。","俗事祇今长刺促，可人自昔费招呼。","忧时恨不百子骏，背我宁堪二大夫。","舣纁黄昏不成别，画成江上送行图。"]},{"t":"再用宋兵部韵送刘左史","f":"七言律诗","c":["絷维不住谷中驹，爱恋徒占屋上乌。","开汉楼前迎剑骑，临津门外罢传呼。","宅家未忍忘贤传，衡宇胡为戒仆夫。","阁束衣冠聊一笑，不为耐辱司空图。"]},{"t":"己未唱第后谢恩诗","f":"七言律诗","c":["圣皇学问富春秋，当宁宵衣渴壮猷。","鹄立银袍天北阙，龙飞金榜殿西头。","彤池缪对三千字，黄甲俄输一二筹。","初学粗知存大体，纷更要洗洛阳羞。"]},{"t":"马少卿挽诗","f":"七言律诗","c":["重葩殗叶露华浓，不忝家声得似公。","言行端和今世楷，貌心醇质古人风。","直将趋走二三节，换取宽閒五百弓。","如此名卿缘手尽，同时更送竹溪翁。"]},{"t":"丹棱杨子金挽诗","f":"五言律诗","c":["气象古君子，渊源朝大夫。","里门车下泽，客舍马青刍。","霜柏寒逾劲，庭荆老不枯。","只愁儿返哺，不及见飞乌。"]},{"t":"从事郎致仕史挽诗","f":"七言律诗","c":["人为浮名若挂钩，夫君知命独休休。","东都门外蚤辞禄，西岘山前不入州。","告第书归泉壤底，满籯金在架签头。","当年勇退称三老，此老胡宁不慭留。"]},{"t":"六月十四次韵樊武仲喜雨","f":"七言律诗","c":["谁信夔夔解感神，嘤嘤赤子母心熏。","为将一滴翻瓢水，散作千家举锸云。","大化无端长寂寂，众形有欲自芸芸。","更须尽挽天河水，亟与三边洗恶氛。"]},{"t":"支大监挽诗","f":"五言律诗","c":["四海李南纪，蚤从山斗韩。","耻担兵部米，宁着大夫冠。","人舐黄金笔，天颁白玉棺。","平生一厚字，千古薄夫宽。"]},{"t":"文彭州挽诗","f":"五言律诗","c":["二仲婵嫣起，清修自一家。","践涂中险阻，宰郡晚光华。","气燄奔金虏，威棱憺铁耶。","料应九峰下，朝露泣姚花。"]},{"t":"王处士挽诗","f":"五言律诗","c":["槿篱山下屋，桐帽水边村。","遗子方寸地，传家廿四言。","芳荪生夕秀，衰柳带秋昏。","千古堂堂恨，青云落泪痕。"]},{"t":"王宜人挽诗","f":"七言律诗","c":["门谱谁誇郡姓强，是家元自孝廉郎。","长来但识诗书贵，老去不知簪珥香。","吏部生涯瓶里粟，夫人宗事橐中装。","他年点检挈庵稿，宁愧欧公志薛杨。"]},{"t":"王宝谟挽诗 其三","f":"楚辞体","c":["昔我仕龟城，犹能友宁馨。","记曾?别酒，俄遽隔泉扃。","顷刻成三世，凄凉隔九龄。","魂兮谁与作，吾友许公铭。"]},{"t":"王宝谟挽诗 其二","f":"楚辞体","c":["泸江鲛夜泣，柳庙鹤秋飞。","零露伤兰颖，凄风撼王徽。","焄蒿恍兮惚，精爽是邪非。","岂必存亡问，吾知全以归。"]},{"t":"王宝谟挽诗 其一","f":"五言律诗","c":["宁怀会稽绶，不遗帝城书。","仕止四千石，年开八秩初。","倾囷除旱魃，防岸免民鱼。","欲识恩田广，衔哀到小胥。"]},{"t":"王总卿生日 其二","f":"七言律诗","c":["浮云䆉稏卷晴畴，一目天隅尽好秋。","路有醉人挑袯襫，边无嘶马趁兜鍪。","开张叶气凭弧矢，收拾丰年报冕旒。","小小经纶已如此，不应留滞古梁州。"]},{"t":"王总卿生日 其一","f":"七言律诗","c":["上到青天更上头，蜀人犹记旧星轺。","安弦在昔犹危柱，挂壁于今倚大弨。","棠树留春便野茇，桂花和月引仙瓢。","风云不隔连天栈，门户三槐拂绛霄。"]},{"t":"计处士挽诗","f":"五言律诗","c":["我之外王父，早岁识殷州。","落落双蓬鬓，萧萧一衲裘。","天时四不出，人事百无忧。","事业虽亡试，全归閟一丘。"]},{"t":"乐府君挽诗 其二","f":"五言律诗","c":["大雅云亡久，流风尚典刑。","赋登司马室，诗授伯鱼庭。","不及瞻郎罢，犹能识宁馨。","芜辞书琬琰，敢齿蔡邕铭。"]},{"t":"乐府君挽诗 其一","f":"五言律诗","c":["缣缃迂活计，屋壁老功夫。","月暗乌声迥，霜寒雁影孤。","江灵知孝子，天赋厚耆儒。","剩馥多沾丐，于今道未臞。"]},{"t":"乐隐君挽诗","f":"五言律诗","c":["人畸天则偶，俗隘我常优。","谩道蚿怜鳖，终成鹊避鸠。","蹇驴花露晓，孤雁稻云秋。","想见招魂曲，人人说少游。"]},{"t":"冯夫人挽诗","f":"五言律诗","c":["解道先天易，能哦击壤诗。","只因居有习，毋谓女无仪。","在姆师逡立，从夫妇得咨。","暮年尤慰意，玉婿作门楣。"]},{"t":"史仓使约登齐山自弄水亭过清溪桥至壶天洞洞乃史新作或曰此即左史洞又至华盖洞翠微亭史仓索赋","f":"七言律诗","c":["自分宇宙有江山，独觉新年胜故年。","水拍大堤人射地，路盘绝崄马行天。","松萝苒苒开还密，洞谷谽谽断复穿。","理道元来无隐尔，人从纸上看天渊。"]},{"t":"史合州挽诗","f":"五言律诗","c":["昔忝东川使，知公才谞长。","莫邪宁是利，薤本未为彊。","横槊悲秋塞，凝香送夕阳。","边关正多事，感慨卧龙冈。"]},{"t":"史制干晦甫挽诗","f":"七言律诗","c":["菑川元自属公孙，竟策词场第一勋。","理有是非宁挠夺，官无大小只忧勤。","纷纷白地皆滩濑，豁豁青天亡片云。","满腹诗书竟何用，泉台暧暧日西曛。"]},{"t":"史致政挽诗","f":"五言律诗","c":["口道先生易，躬行君子难。","浮荣残梦觉，活计一般酸。","日晚乌声急，风高雁影寒。","行藏付千载，反覆要人看。"]},{"t":"正月九日北山雍熙寺约同官","f":"七言律诗","c":["自从寒陆爽乾坤，律吕还宫岁换辰。","历纪人正才九日，斗移天位已三春。","销磨壮士姑随俗，牵引閒心苦为人。","终愧时艰才力短，只将民命倚洪钧。"]},{"t":"生日和辛江陵即席韵 其二","f":"七言律诗","c":["笑语声中别有天，巫云楚岫玉明船。","冷风入坐酒无力，斜日媚空花欲然。","猎猎旗风犹夏五，摇摇帆影立秋千。","他时辇路追今梦，傥许陪公发未宣。"]},{"t":"用张子益教授韵送虞退夫西归","f":"七言律诗","c":["子已江头戒棹郎，卬须何事未乘方。","须看此意关时数，不为斯人自肺肠。","白傅徒然泣商妇，毛生岂解出王樯。","卬虽不敏真知得，为子临岐釂一觞。"]},{"t":"用李致政韵题临邛陈氏所居吕仙所留回道人来四字","f":"七言律诗","c":["负瓮城边閒日月，翻环门上几春秋。","东阳谩识榴皮字，南郭曾偕柳树游。","踏雪飞鸿痕偶在，寒潭过雁影无留。","至人御气无今古，妙处疑同上下流。"]},{"t":"用蒋成甫韵贺虞退夫生子且以相名之","f":"七言律诗","c":["秦雍孙曾尚典刑，只将一念答天明。","震雷殷地勾萌达，解雨鸣春涧谷声。","阶玉正看联羯末，籯金安足拟贤成。","相门为我成宅相，我欲将儿以相名。"]},{"t":"用樊武仲致政韵饯黄户部","f":"七言律诗","c":["七载赍身入楚乡，谁将平坂换羊肠。","觉来亲友浑依旧，触处江山不改香。","正引德星成胜集，更忻郎宿下垂光。","人生行止时为大，膜外浮荣蚁穴王。"]},{"t":"仲女挽诗","f":"五言律诗","c":["荆江春梦断，虞殡夜魂孤。","未及陪宗室，应难祔舅姑。","一时母从子，百岁妇随夫。","此礼缘情制，临风老泪枯。"]},{"t":"任重庆挽诗","f":"五言律诗","c":["诸任方衮衮，惜也大任君。","曲突人谁信，扣阍天不闻。","胆随豪满干，齿为愤穿龈。","莫挽泉台恨，周箫咽涧云。"]},{"t":"再次沧江韵 其二","f":"七言律诗","c":["野迥江空云意閒，清风唤客度东关。","掺掺竹柏青垂地，炯炯宾朋玉立山。","酒为心知一开口，话逢理到两舒颜。","啸吟风月江头路，此意羲皇向上还。"]},{"t":"再次沧江韵 其一","f":"七言律诗","c":["夏畦初雨桔槔閒，读易幽人昼掩关。","厚筑根基方考室，不辞卷撮要为山。","剩栽晚岁松筠友，长伴沧江冰雪颜。","门外斜阳迷客路，屋中行李去家还。"]},{"t":"再和","f":"七言律诗","c":["芹宫日晚守祠斋，争见花如火齐堆。","不复少年黄犊健，任令急景白驹催。","繁红才伴栗留至，众绿又惊鶗鴂来。","到会意时须命酒，莫论花谢与花开。"]},{"t":"再和颠字韵时方议开边","f":"七言律诗","c":["鼎象亨调戒在颠，或捐常馔美时鲜。","鸷形不匿麇投麓，剑影虚张蛟绕船。","壮观要还全盛日，图回须似中兴年。","掩关雷雹惊春梦，忧国丹心只自怜。"]},{"t":"刘少监挽诗 其二","f":"五言律诗","c":["天子龙飞日，东征与子同。","俄将满船月，换却打头风。","志尚观其始，规模识所终。","人才眇然甚，胡不慭遗公。"]},{"t":"刘少监挽诗 其一","f":"五言律诗","c":["端重嗤浮俗，深沈烛事几。","上天陪将相，宥地赞枢机。","辰告言犹在，朝回事已非。","空贻郎罢叹，不见子行归。"]},{"t":"孙夫人挽诗","f":"五言律诗","c":["庄重知为女，宽和解相夫。","母慈均众子，妇道尽皇姑。","春日鸣抟黍，秋风撼毕逋。","尚迟彤管笔，宿草卧龟跗。"]},{"t":"宇文泸州挽诗 其二","f":"五言律诗","c":["风壑昂脩干，霜空突翠峰。","介然疑苦硬，行处独从容。","不忝南轩嗣，奚惭北学宗。","巫阳招不复，暧暧日高舂。"]},{"t":"宇文泸州挽诗 其一","f":"五言律诗","c":["笃信宁违俗，质行非近名。","室无官烛泪，庖有甑尘生。","吏不知厮卒，家毋役叟兵。","兹犹馀事耳，彻底是真清。"]},{"t":"宇文枢密挽诗 其二","f":"五言律诗","c":["夷考公言行，真成肃悯孙。","星枢绳懿武，月殿媲隆恩。","契阔成三世，凄凉隔九原。","壮夫襟上泪，并为两师垣。"]},{"t":"宇文枢密挽诗 其一","f":"五言律诗","c":["人物眇然甚，天胡不慭公。","北风鸣槭槭，西火乱蓬蓬。","襄鄂谁专阃，江淮孰总戎。","是应当馈叹，曩日镇江功。"]},{"t":"安宣抚生日 其一","f":"七言律诗","c":["知是皇家几世仁，天开人物作长城。","元崇雅号济时相，景略真成间代英。","天路旂常铺绩用，中原草木识威名。","北征西略公馀事，应念同胞百万生。"]},{"t":"安宣抚生日 其二","f":"七言律诗","c":["疏戆烦公刮目看，肯持谀语祝加餐。","千钧弩上机宁易，百尺竿头步转难。","事遇快时聊复忍，民当急处略须宽。","扫除荆棘栽梨枣，累璧重圭耐岁寒。"]},{"t":"安总领生日 其一","f":"七言律诗","c":["犹记仙翁护玉关，版图半壁手提还。","每惊荡潏风波后，多谢经纶父子间。","元是烂柯观已熟，故应当局祇如閒。","几人钱谷鞭中老，双鬓何曾点一斑。"]},{"t":"安总领生日 其二","f":"七言律诗","c":["祝公不作语啾啾，陛下凭公释顾忧。","往误叵堪成铁错，后图犹可保金瓯。","饮江共喜无胡马，屯渭悬知有木牛。","虎也肤公康是似，愿歌江汉美宗周。"]},{"t":"成都杜五一府君之葬某新有丧不得为文以侑虞殡命儿冲代赋","f":"五言律诗","c":["尚记维川死，今年又哭公。","琴声辞夜月，书叶卧春风。","儿女数行泪，亲朋十九空。","我翁方念母，忍泪课儿冲。"]},{"t":"成都教授史君挽诗","f":"五言律诗","c":["槁乾迂事业，讲授老功夫。","日暮乌声急，山空鹤影孤。","高谭霜皎洁，及物雨昭苏。","已矣公何憾，于今道未臞。"]},{"t":"朱邵州挽诗","f":"七言律诗","c":["杏园犹记赏花同，忍看前旌照眼红。","民命一丝悬晷刻，仁心触处作春风。","棣华韡韡天伦厚，湑叶裳裳世泽隆。","万事纷纷缘手尽，只将孝友诏无穷。"]},{"t":"次王万里愁霖","f":"七言律诗","c":["江声砧杵入层楼，预作人閒八月秋。","虹外挂无穷远思，雁声鸣不断新愁。","汉淮赤地不知里，巴蜀青天更上头。","蹇我康时分无策，只祈一饱暂销忧。"]},{"t":"次肩吾庆生日韵 其二","f":"七言律诗","c":["我友忧时发满梳，殷勤勉我用诗书。","情知分义如何废，可使才能自有馀。","气血渐衰多病后，创夷转甚数年初。","梦魂惯识归来趣，长傍山椒撷稻疏。"]},{"t":"次肩吾庆生日韵 其一","f":"七言律诗","c":["谩阅人间五十年，年来道远思悠然。","一心可使乾坤位，五性元钟父母全。","为己工夫浑间断，满头岁月浪推迁。","更无益友相扶植，平地羊肠仆白颠。"]},{"t":"次肩吾庆生日韵 其一","f":"七言律诗","c":["男儿生世果何事，卜士诗之闾史书。","内美元非私正则，天彝岂但付胥馀。","滔滔大化亘千古，职职群生同一初。","此事年来才信得，从前浪走只成疏。"]},{"t":"次肩吾庆生日韵 其二","f":"七言律诗","c":["山中兀兀不知年，但数前山䓞火然。","人笑腰无金可佩，我忻胫与玉俱全。","圣贤面目昼三接，简册期程日九迁。","此事知心君有几，不妨相伴各童颠。"]},{"t":"次韵丁大监见怀 其一","f":"七言律诗","c":["行藏去就各随时，敬怒嫌疏忍奋飞。","正怕霜严天宇净，敢誇舟载月明归。","生松有梦还公固，化鹤何心驻令威。","独抱遗编看千古，昔人历历未应非。"]},{"t":"次韵中秋风雨中约客叶元老有诗","f":"七言律诗","c":["长雨顽云处处山，浃旬浑不露天悭。","鱼旟未兆心如醉，鸿雁关情鬓欲斑。","月体晦明犹偶尔，酒肠舒惨亦浑閒。","只将愚虑酬佳赠，未必骚情不破颜。"]},{"t":"次韵王常博题赠江陵乐德佐 其二","f":"五言律诗","c":["三十有三载，好风吹又来。","清坚霜后竹，冷澹雪边梅。","世事忧千绪，家山肠九回。","江头一樽酒，烟雨暗章台。"]},{"t":"次韵王常博题赠江陵乐德佐 其一","f":"五言律诗","c":["僇馀甘远屏，分表得生还。","夜雨滴归梦，晓霜彫醉颜。","角巾吾故里，璞玉子荆山。","又作无期别，扁舟上峡关。"]},{"t":"次韵李参政上刘舍人阁学","f":"七言律诗","c":["滔滔陆海与潘江，得似韩渠受籍泷。","天下美官容易得，世间清论苦难降。","龙随凡介便俦伍，鹤耸孤云谁等双。","一马二童吾计决，山中花竹总麾幢。"]},{"t":"次韵李参政见寄 其三","f":"五言律诗","c":["湖畔三顷秫，酿成聊独斟。","积薪伤汲直，求旧感迟任。","梦里牛山峻，吟边雁泊深。","两乡明月夜，应照旧登临。"]},{"t":"次韵李参政见寄 其二","f":"五言律诗","c":["怕放红楼目，浮云断复连。","远看壶聚拓，近视室如县。","耿耿自许国，悠悠谁讯天。","天心那可识，拄颊看晴川。"]},{"t":"次韵李参政见寄 其一","f":"五言律诗","c":["自失鸥边约，应羞鹤上人。","竹荒青翼短，书远墨题亲。","世事方尝胆，时贤谩饮醇。","国疑谁为嗣，公子急振振。"]},{"t":"次韵李参政见谢游龙鹤山诗 其二","f":"七言律诗","c":["有鸟云飞鱼跃渊，圣贤见处自天悬。","流阴卒卒谩空过，斯道寥寥谁适传。","人境恰逢如择地，主宾良晤岂非天。","二章发我无穷思，不慊遗编对圣贤。"]},{"t":"次韵李参政见谢游龙鹤山诗 其一","f":"七言律诗","c":["北山尝乞草堂灵，娓娓高谈析理精。","泼眼溪光无间断，入怀月色太鲜明。","寒毛络石清可数，暝霭蒸山浓欲倾。","相对悠然无语处，古今成败一空枰。"]},{"t":"次韵李参政见遗生日 其三","f":"五言律诗","c":["幸有鹤山房，图书绕梦香。","况惭闻道浅，何苦为人忙。","五斗米非分，三间茅可长。","何当重操几，同踏古松冈。"]},{"t":"次韵李参政见遗生日 其二","f":"五言律诗","c":["月暗书中色，霜彫镜里年。","滔滔时易失，落落意难传。","信己终违俗，随人谩辱先。","输他南阁老，攲玉弄寒泉。"]},{"t":"次韵李参政李提刑见和雁湖观梅","f":"七言律诗","c":["春事何须羯鼓催，好春全看未花时。","雨馀庭院湖光湿，人倚阑干夕暝迟。","正会意时俄起起，到忘言处谩期期。","雁湖饮散人归后，曾问梅花复几枝。"]},{"t":"次韵泸帅范郎中再和所送李季允韵见寄 其一","f":"七言律诗","c":["人老边关未得师，行违久速只安时。","令随天阔风遥岭，语挟春来草梦池。","旧垒无华閒睥睨，新机有句到侏离。","孤衷耿耿无人会，只傍天公作己知。"]},{"t":"次韵泸帅范郎中再和所送李季允韵见寄 其二","f":"七言律诗","c":["新阳拆地唤春归，生意绵绵重此时。","青女卷寒还朔易，朱轮驾暖出咸池。","恩流未渗鱼犹涸，禁网虽疏雉或离。","抚事伤时无限意，冯梅折寄故人知。"]},{"t":"次韵苏和甫雨后观梅","f":"七言律诗","c":["岁寒宾友伴萧萧，客气无根已尽凋。","疏影照人骚梦冷，清香彻骨醉痕销。","话逢理到春生坐，饮为心知月满瓢。","更祝天公多雨麦，时携乐酒酹芳条。"]},{"t":"次韵知常德袁尊固监丞送别四诗 其四","f":"七言律诗","c":["夕阳舂处是吾家，水绕山环路转赊。","蹙蹙四方浑未定，茫茫大化渺无涯。","归来已恨十年晚，老去空嗟两鬓华。","各愿及时崇令德，万钟于我本何加。"]},{"t":"次韵知常德袁尊固监丞送别四诗 其一","f":"七言律诗","c":["试把行藏为子评，只知尽分敢徼名。","出如有益殷三聘，用不能行鲁两生。","此道古人如饮食，后来灶婢或猜惊。","子云亦号知书者，犹把商山作采荣。"]},{"t":"次韵知常德袁尊固监丞送别四诗 其三","f":"七言律诗","c":["别来岁月尔滔滔，流落天涯忽此遭。","万木辞荣秋意澹，百川归壑岸容高。","笑看海上两蜗角，閒秃山中千兔毫。","若向颜曾得消息，直须奴仆命离骚。"]},{"t":"次韵知常德袁尊固监丞送别四诗 其二","f":"七言律诗","c":["孔训元无实对名，只言为己与求人。","能知管仲不为谅，便识殷贤都是仁。","义利两涂消处长，古今一理屈中伸。","自从圣学寥寥后，千百年谁信得真。"]},{"t":"次韵范少才在峡中寄李季允 其二","f":"七言律诗","c":["大明临照职方州，汉沔江淮澹若油。","剪薙荆榛开跸路，护持杞梓耸岑楼。","朝纲人为诸公喜，国体谁知志士愁。","谠议胡公不可作，奉常今说有黄侯。"]},{"t":"次韵范少才在峡中寄李季允 其一","f":"七言律诗","c":["蜀艇云奔下固陵，一壶浮峡便千金。","子来我往才交臂，人涉卬须又苦心。","北向虽无一矢发，西风不受半尘侵。","是非得丧今休问，喜见戈枪卧绿沈。"]},{"t":"次韵费同叔解嘲 其一","f":"七言律诗","c":["乞得身来作外臣，冲然肺腑自韶钧。","咸酸独觉水中味，形影相依镜里真。","入户方闻夫子乐，近前孰试相君嗔。","昊天明旦司游衍，环堵严于百万人。"]},{"t":"次韵费同叔解嘲 其二","f":"七言律诗","c":["低头涸辙问波臣，沃以嘉言力万钧。","逆耳倒言诚爱助，解嘲谢谤返离真。","若微君告谁能及，幸不吾欺乃敢嗔。","彼是纷纷姑勿道，所期终诲作全人。"]},{"t":"次韵监试潼川提刑张兵部有怀家山木犀","f":"七言律诗","c":["形安宇泰即吾乡，花解随人到处黄。","何事归心起张翰，有来妙语出君房。","荣枯境里自殊观，造化机中无别香。","不见儋州安乐法，随花随客作重阳。"]},{"t":"次韵黄侍郎生子","f":"五言律诗","c":["未用占呱泣，悬知头角疏。","芝兰庭殖殖，梧竹厦渠渠。","虎子驱黄犊，禽儿驾小车。","乃翁何以遗，行李五车书。"]},{"t":"次韵遂宁府宴贡士即席赋 其二","f":"七言律诗","c":["谁把浮华变古风，颓波衮衮日奔冲。","人情容易随流去，此道分明触处逢。","学似董晁犹有累，文过元白愧无宗。","诸君自此皆升矣，更向根基厚自封。"]},{"t":"次韵遂宁府宴贡士即席赋 其一","f":"七言律诗","c":["过尽一春花信风，鱼天鼓浪送蒙冲。","凤翰有目争先睹，牛角无人叹不逢。","选试谩称新汉使，作成端属旧春宗。","鹿鸣剩作中和曲，嶉送飞黄出蚁封。"]},{"t":"次韵虞万州见寄除夕江村饯腊 其二","f":"七言律诗","c":["处士西城落照边，春风吹袂意泠然。","閒中受用封千户，圣处功夫禄九迁。","竹外缓觞留急景，沙头饱饭看丰年。","诗来发我无穷思，拟上沧江别看天。"]},{"t":"次韵虞万州见寄除夕江村饯腊 其一","f":"七言律诗","c":["非我江山许我赊，有涯生事不无涯。","雨添饼饵村村秀，风作羹胹树树花。","行玉盘中看物化，缕银幡里感年华。","初春心事谁人解，梦落沧江处士家。"]},{"t":"次韵虞万州沧江海棠","f":"七言律诗","c":["维摩老子菌生庵，门外沧江绿正涵。","夜雨村村拆花柳，春风日日长桑蚕。","晚妆才记海棠睡，朝色俄看禁药酣。","造化新功镇如此，抚诗往往发余惭。"]},{"t":"次韵虞永康读易有作","f":"七言律诗","c":["室中万象本宽閒，门户何曾顷刻关。","未始有时观太极，不终止处认兼山。","人文自昔先牺昊，天赋云谁不孔颜。","有志未能今得友，从今迷路傥知还。"]},{"t":"次韵虞永康谢余过沧江","f":"七言律诗","c":["雨馀云簇数峰奇，公子江头客款扉。","白舫青帘乱平渺，黄鸡浊酒话清微。","稻畦千顷睟生色，竹日一川摇静晖。","坐久东山初月上，恍疑赤壁旧时矶。"]},{"t":"次韵虞永康题沧江书院","f":"七言律诗","c":["解后沧江半日閒，一川风物闯柴关。","正从逝处识流水，更向静时观远山。","有咏皆春谁与点，无时不学子睎颜。","相逢一笑忘言处，月堕波心不记还。"]},{"t":"次韵□丞兄闻丁卯十一月三日朝报 其一","f":"七言律诗","c":["龙章晨下九重关，帝敕元凶出羽山。","揭日行空破昏闇，乘风纵燎绝神奸。","须看文正昭陵日，孰与忠宣元祐间。","更愿和平培治体，儒臣千岁侍天颜。"]},{"t":"次韵□丞兄闻丁卯十一月三日朝报 其二","f":"七言律诗","c":["傥来得丧本无关，或为鸿毛加太山。","纵昔尹鼯宁有损，及今投裔枉为奸。","公私界分分明甚，狂圣途程念虑间。","初学粗知真富贵，从今克复愿睎颜。"]},{"t":"江州司马安君挽诗","f":"七言律诗","c":["当年风雨脊令原，共挈凶颅奏凯旋。","弄破峨眉山月影，慵移湓浦荻花船。","浮云都似梦中觉，妙句犹于身后传。","肠断美人湘水隔，凭鸿寄泪识新阡。"]},{"t":"约任千载大卿同王万里杨仲博汎湖任赋二诗和其韵 其一","f":"七言律诗","c":["满目亲朋似故乡，梦邪非梦梦何长。","春风坐上白云屦，玉鉴光中明月珰。","酒到湖山嫌逊避，话逢气类省称量。","谢家内集如斯否，一味诗书无别香。"]},{"t":"约任千载大卿同王万里杨仲博汎湖任赋二诗和其韵 其二","f":"七言律诗","c":["翠舫青帘白玉舟，风轻日淡相兹游。","芙蓉覆地锦衾烂，杨柳雕空印篆缪。","月上酒痕浑未觉，山撩诗思浩难酬。","颇怜此会何时又，相伴江湖归去休。"]},{"t":"自长宁阡过灵泉兄墓爇黄经从隈支以归","f":"五言律诗","c":["晨策犯层巅，危如峭壁缘。","溪明人在地，路绝马行天。","松倚露云立，稻依霜雨眠。","不知岁年晚，抚事亦悠然。"]},{"t":"舟至合江度周卿以诗相迓次韵","f":"七言律诗","c":["雨满长空水拍畴，荔香松色倚江流。","半窗灯火千年梦，万里风波一叶舟。","谩道班卿若仙去，谁知谢傅正同忧。","西归待我期相告，横被风师三日留。"]},{"t":"观南堤","f":"七言律诗","c":["吏报南郊役事休，好风吹袂到江头。","长堤饮水马非马，叠石护田牛戴牛。","处处女筐蚕望岁，村村社鼓麦祈秋。","守臣不办康时策，只把农夫作己忧。"]},{"t":"许侍郎同饮郊外王氏亭分韵得风字","f":"七言律诗","c":["万绿成帷涨晚空，不知门外几番风。","月拖树影阑干角，烛挟花阴酒盏中。","饮隽青山如有问，曲终远意浩无穷。","登临此地知多少，气味应难似此同。"]},{"t":"许侍郎挽诗 其二","f":"五言律诗","c":["近事君知不，王心莫与宁。","融风薄台里，秋雨暗前星。","鸿集稻粱少，虎嘷川谷腥。","人才关世道，敛涕为公铭。"]},{"t":"许侍郎挽诗 其一","f":"五言律诗","c":["杏园春接袂，蓬省夜分灯。","权相不吾以，贵人惟子憎。","虽云殊爵位，均不愧交朋。","顾影追前事，悠然涕满膺。"]},{"t":"过虎头狼尾滩避险出陆至谭晋仲故居有谢公昌国刘公德脩薛公仲章诗用谢韵有赋 其二","f":"七言律诗","c":["纷纷操罟入山林，我自终朝不获禽。","远物只知肥遁利，穷幽不问浚恒深。","毕逋啼日满荒戍，款段行云供醉吟。","宇宙穷空岁迟暮，平沙独立数寒金。"]},{"t":"过虎头狼尾滩避险出陆至谭晋仲故居有谢公昌国刘公德脩薛公仲章诗用谢韵有赋 其一","f":"七言律诗","c":["尚记翩然下帝傍，七年才入屈公乡。","山衔西日去家近，风递北氛吹袂凉。","新事感伤心力短，旧交零落话头长。","况堪刘薛吾师友，黄壤堂堂閟夜光。"]},{"t":"齐安郡向夫人挽诗","f":"五言律诗","c":["祥符名相裔，元祐宰臣孙。","展也晋秦匹，烂其韩姞门。","世纷冰似冷，壸范玉如温。","千古峨眉月，争辉北客魂。"]},{"t":"何府君挽诗 其一","f":"五言律诗","c":["林泉间富贵，缣素老功夫。","古树檠苍干，脩庭拥碧梧。","只安车下泽，不侈骑传呼。","轧轧成都道，还家日未晡。"]},{"t":"余既赋诗坐客请以唐人家花车斜韵同赋醉中作五十六言","f":"七言律诗","c":["人生偶被浮名误，往往贪程不识家。","醉眼乱穿青草屐，狂心长恋碧桃花。","举头大道平如掌，入鬓韶光转似车。","是乃吾忧今赠子，情亲语直字欺斜。"]},{"t":"别东叔西叔二兄于遂宁门外","f":"七言律诗","c":["毕逋枝上晓光和，日日庭闱盼树柯。","风送骊歌惊短梦，云拖鸠雨湿长坡。","母心念子无时足，王事催人不奈何。","但祝爱身崇令德，长教此意得天多。"]},{"t":"即席和丁夔帅送行诗韵 其二","f":"七言律诗","c":["眼明织翠剪新诗，勉我当今尚可为。","知觉斯民知觉我，溺饥天下溺饥谁。","志亨不管身穷达，谊正宁论效疾迟。","倒尽玉瓶谈未了，沙头忍泪与君辞。"]},{"t":"即席和丁夔帅送行诗韵 其一","f":"七言律诗","c":["人生行止莫非天，去国重来十七年。","学自孔颜期有是，道非尧舜敢陈前。","忧时正念梁瓯缺，视己当如赵璧全。","若得时清身不辱，尽教人道是登仙。"]},{"t":"吴府君挽诗","f":"五言律诗","c":["笃信宁违俗，徐行不竞时。","与人交乐易，处世事平夷。","甚矣古常者，伤哉今已而。","龙山春夜月，长照凤皇枝。"]},{"t":"应提刑以十五日和韵见示再次韵","f":"七言律诗","c":["大圆垂象晓群黎，犹送昨宵畏满诗。","要看天行嫌位亢，若言人事恶功亏。","升于正处元为利，坎到盈中乃识时。","疑我冰轮公赐厚，敢申馀义副襟期。"]},{"t":"张大著以韩持国绿樽红妓事再和见戏复次韵 其二","f":"七言律诗","c":["壮心十五亦狂颠，十五年来洗濯鲜。","负郭元无三亩宅，浮家安有五湖船。","焚香读易谢来况，饮绿围红回长年。","不是柳桃曾作恼，安知世味有妍怜。"]},{"t":"张大著以韩持国绿樽红妓事再和见戏复次韵 其一","f":"七言律诗","c":["世路羊肠几覆颠，如君操行雪朝鲜。","书胸满贮宣和库，学力要装元祐船。","剩喜孟龙来并世，肯呼祢鹗与忘年。","闭门笄珥无膏沐，不作倾城冯小怜。"]},{"t":"张运判挽诗","f":"五言律诗","c":["悃愊汉循吏，咨询周使臣。","知心三坐主，报国两门人。","綵绣方趋户，丝麻已在身。","至今寒食路，孺慕镇如新。"]},{"t":"张运判之母吕宜人挽诗 其二","f":"五言律诗","c":["锦乡閒日月，象服俨山河。","富贵吾无羡，平反尔几何。","相依在岁晚，不竞得天多。","欲报无终极，悲风振蓼莪。"]},{"t":"张运判之母吕宜人挽诗 其一","f":"五言律诗","c":["昔在伤皇辟，子行犹不归。","嫠居言有则，丧事礼无违。","轲母三迁教，莱儿七十衣。","至今霜月夜，松竹带芳徽。"]},{"t":"张隆州挽诗","f":"七言律诗","c":["行马门阑宰胄巍，高冠长佩独委蛇。","紫微自有申公学，太史还从从祖知。","静嘿无非蒙力处，功夫全在不欺时。","故家遗俗寥寥甚，忍听虞歌薤露悲。"]},{"t":"张隐君挽诗","f":"五言律诗","c":["触事无非学，非儒果误身。","体中识天地，笔底定君臣。","安乐堂前月，希夷枕上春。","是应家有子，不止活千人。"]},{"t":"李池州和韵见寄再赋以答之","f":"七言律诗","c":["晨策随乌瞰屋山，面前咫尺隔同年。","邛人自爱橘中乐，晋客惊逢洞里天。","行傍輶轩心半醉，坐看戟卫眼双穿。","西风一夕惊龙睡，撼取明珠出九渊。"]},{"t":"李怀安挽诗","f":"五言律诗","c":["乡邑赖蓍龟，天胡不慭遗。","与人交乐易，处世事平夷。","甚矣古常者，伤哉今已而。","抚时怀牧守，忍泪读刘碑。"]},{"t":"李制置生日 其一","f":"七言律诗","c":["玉堂人住玉堂山，公论推排授将坛。","朔垒令严精采异，甘泉烽息顾忧宽。","北边旧叹无颇牧，西贼今闻有范韩。","夏屋不知几崇广，唤回春燕下林端。"]},{"t":"李制置生日 其二","f":"七言律诗","c":["披荆重立小朝廷，风递南薰入扇巾。","大势已冯天祚宋，中兴更赖岳生申。","扶持命脉还吾蜀，消息精神运此身。","人愿武公归入相，我祈河内且留恂。"]},{"t":"李参政见招游龙鹤山归途有作 其二","f":"七言律诗","c":["乱涧穿云十里閒，好风吹袂出重山。","潺潺流水半归壑，唧唧候虫皆闭关。","兴念岁时惊变态，静观物化识回环。","并溪的皪梅花树，已带明年春事还。"]},{"t":"李参政见招游龙鹤山归途有作 其一","f":"七言律诗","c":["上有高峰树倚天，下临深涧水生烟。","陶镕泉石山中相，舒卷云霞地上仙。","松色呼儿开后槛，笋舆为客过前川。","不因同落天涯久，那得岩扉共此缘。"]},{"t":"李参政约客访西郊海棠予以斋禁不与","f":"七言律诗","c":["十日花期九日斋，相园红锦烂成堆。","不将小雨轻阴驻，刚把和风暖日催。","诗笔都随许昌去，春光不待牧之来。","要知荣悴适然耳，明日荼蘼芍药开。"]},{"t":"李季允作吞云楼索诗和总漕韵答之 其一","f":"七言律诗","c":["栅新飞观走狐嘷，楼鹤洲鹦贺此遭。","整暇旌旗登巀嶪，奔波舟楫笑嗷嘈。","宅中平后规摹拓，烛理明时运量高。","须信是间天地似，词人云梦特秋毫。"]},{"t":"李尚书被召过泸临发之日官吏以行香日分追送不及明日尚书自合江诘后期次韵以谢","f":"七言律诗","c":["黄鸡喔喔丑前催，拟效张侯夜半来。","残梦方随僧梵去，挐音已听客帆开。","江皋望极空留恨，陛下忧深正急才。","已赋明伦相赠勉，更思桃李及时栽。"]},{"t":"李郎中挽诗 其二","f":"五言律诗","c":["解道公行止，江东老父兄。","群州垂瘵死，肤使为更生。","民裕身逾瘠，时危命亦轻。","浔阳江上月，犹傍谏书明。"]},{"t":"李郎中挽诗 其一","f":"五言律诗","c":["太息金泉守，西归空好音。","孳孳求友意，恳恳爱君心。","谋道身多阨，忧时力不任。","怀人今永已，为世一沾襟。"]},{"t":"李顺庆挽诗","f":"五言律诗","c":["蜜绍方闻学，亲承太史传。","才资元近厚，辈行最推贤。","七任二千石，分符三十年。","天廷无一迹，归伴壑龙眠。"]},{"t":"李德迈挽诗","f":"七言律诗","c":["鸣嘤出谷邈难亲，断雁辞行不可群。","论事期期钳在口，逢人额额齿穿龈。","乾坤许阔犹有碍，风雨满前如不闻。","肠断天津邵夫子，东篱掩泪立孤云。"]},{"t":"李德秀致政以其生日前一日约士友至长庆院访梅花山茶因以为寿","f":"七言律诗","c":["流年苦被雪霜催，惟有山中自四时。","寒色慭花妆岁晚，晓阴挟雾放春迟。","似嫌俗客不同调，留与高人共胜期。","但愿多书冲祐考，与君长伴岁寒枝。"]},{"t":"杨夫人挽诗","f":"七言律诗","c":["行应珩璜女子师，荐修蘋藻大夫妻。","礼门总是行持地，宦海元非爱欲泥。","翚翟相传犹白凤，鹓雏可伏胜黄鸡。","柳州念妹嗟何及，令德章章银笔题。"]},{"t":"杨处士挽诗","f":"七言律诗","c":["丁年已分与时违，便把书棚嘱付儿。","峨岭秋寒千古意，符溪春暖一筒诗。","彩云来往吾何与，草露消磨我自知。","含笑黄泉应不恨，桂华犹有未开枝。"]},{"t":"杨仲远挽诗","f":"五言律诗","c":["属我铭先竁，元符事益光。","十年黄壤梦，再世短松岗。","楼外焄蒿集，阁前名节香。","吴钩无处挂，刍束寄诸郎。"]},{"t":"杨极父挽诗","f":"五言律诗","c":["高堂元祐脚，下泽少游乡。","自得林泉趣，不登声利场。","年方荣四豆，日已下三商。","有子翁无咎，存心味更长。"]},{"t":"杨叔介挽诗","f":"五言律诗","c":["尚记少年场，英英兀老苍。","鄂不齐挺秀，兰茁竟摧芳。","老尽凌云气，悲成捉月狂。","若人奇且折，此事费平章。"]},{"t":"杨尚书生日 其二","f":"七言律诗","c":["三边头绪正相寻，云气模糊尚积阴。","已喜龙荒通汉使，更须帝梦起商霖。","功名本自于人薄，家国相关此念深。","共指岷峨祝公寿，鬓华未听晓霜侵。"]},{"t":"杨经母范氏挽诗","f":"五言律诗","c":["大父生逢世，严君死守城。","尊章全急义，娣姒得贤名。","夫子行无玷，男儿学有成。","典刑今已矣，风雨送红旌。"]},{"t":"杨修撰挽诗 其一","f":"五言律诗","c":["早辞天子诏，晚挂大夫车。","文雅三朝旧，风流二祖馀。","眼前甲乙石，胸次丙丁书。","自古谁无死，前休得似渠。"]},{"t":"杨修撰挽诗 其三","f":"五言律诗","c":["玉树擎双干，灵椿老一株。","林泉閒富贵，屋漏静功夫。","靖节自为传，耆英还有图。","碑材徒镇石，此墓不须谀。"]},{"t":"杨修撰挽诗 其二","f":"五言律诗","c":["东都方枕奠，方镇尚根盘。","不得裴中立，谁承田季安。","威棱行阃外，声绩在朝端。","犹使江阳隶，闻风亦胆寒。"]},{"t":"杨隆庆挽诗","f":"五言律诗","c":["夜雨撼雍渠，春风载毕逋。","畏途摇短梦，壮志束长湖。","如此奇男子，终于朝大夫。","鲜原千字诔，赖有少公苏。"]},{"t":"泸贡士二十人端平元年手书增郡国贡士员泸增二人是岁贡于东西路转运司者各二人以五月庚戌合寮吏宴于郡之正牙歌鹿鸣以遣之 其二","f":"七言律诗","c":["天地中间着此身，合将位育入经纶。","阴阳固自生成我，爵禄安能富贵人。","利欲当权心退舍，诐淫得路俗迷津。","诸君自此腾骧去，愿以先知觉此民。"]},{"t":"泸贡士二十人端平元年手书增郡国贡士员泸增二人是岁贡于东西路转运司者各二人以五月庚戌合寮吏宴于郡之正牙歌鹿鸣以遣之 其一","f":"七言律诗","c":["皎日中天万国明，恢恢贤路庆端平。","月正元日下书诏，二十六人登姓名。","西泽射陈狸首节，东廉歌奏鹿鸣声。","谬侯何幸身为驾，要示周行玉女成。"]},{"t":"陈寺丞挽诗 其二","f":"五言律诗","c":["圣主搜贤诏，愚臣荐士书。","高冈看治凤，灵沼蛰潜鱼。","时数自信诎，帝心谁戚疏。","臧仓徒扰扰，穷达不关渠。"]},{"t":"陈寺丞挽诗 其三","f":"五言律诗","c":["有子知乎否，苍生命益危。","共伤周赫赫，谁叫庙嘻嘻。","随处皆螗斧，何方不茧丝。","斯人今已矣，抚事转伤悲。"]},{"t":"陈寺丞挽诗 其一","f":"五言律诗","c":["人物晨星似，如公正献家。","皂囊真相业，黄卷旧生涯。","胡不慭遗老，而兴大耋嗟。","天高那可问，泪眼为麻查。"]},{"t":"陈总领挽诗 其三","f":"五言律诗","c":["闻诏弹冠日，颓然秃鬓翁。","当肩百钧重，卷袂两拳空。","既上供军最，方修给饟功。","大钧那可问，曾不慭留公。"]},{"t":"陈总领挽诗 其二","f":"五言律诗","c":["举头西日远，满扇北尘污。","病已关心腹，吾何爱发肤。","变名逃越难，微服过商都。","忽复天开霁，依然只故吾。"]},{"t":"陈总领挽诗 其一","f":"五言律诗","c":["士处宴安日，咸歆节谊名。","范阳徒尔怵，河朔莽然平。","仅识浅利害，恶知真重轻。","开禧忠义传，吾得扈农卿。"]},{"t":"制置丁少卿生日 其二","f":"七言律诗","c":["蜀道今行第几回，天西玉帐又宏开。","鹤归华表人如旧，龟放长河独再来。","屈处观伸霜后菊，消中见息雪前梅。","泸江不解西流去，引领长空酌斗魁。"]},{"t":"制置丁少卿生日 其一","f":"七言律诗","c":["皓皓陵霄独鹤飞，九芙蓉里烂生辉。","青阳少府旧弓冶，白石先生新杼机。","阅尽世纷磨不磷，听渠公论是邪非。","恭惟陛下方亲政，小却犹应伴紫薇。"]},{"t":"和张大著颠字韵 其二","f":"七言律诗","c":["伥伥趋局晓衣颠，妙语飞来墨已鲜。","太一藜然分夜隙，蓬莱海阔接风船。","临邛词客虽末至，淮海签书非少年。","独抱区区无我察，联篇重拜玉人怜。"]},{"t":"和张大著颠字韵 其一","f":"七言律诗","c":["步弱扛丰分疾颠，不将臭腐易芳鲜。","眼前富贵蚁奔垤，膜外功名鸥避船。","忠愤无因尘乙夜，隐忧深觉负丁年。","一窗风雨看书卷，三度京梅雪可怜。"]},{"t":"和李参政正旦闻边报","f":"五言律诗","c":["羽檄连旬月，边尘换岁阴。","捉衿忧见肘，补肉忍剜心。","天远鸿飞急，林疏燕恨深。","直将归往地，都作杀胡林。"]},{"t":"和李参政龙鹤庵庐二首 其二","f":"七言律诗","c":["古往今来一貉丘，行藏有道坎还流。","凤凰池上春风梦，龙鹤山头夜月秋。","閒曳深衣聊独乐，有怀连璧赋三游。","何人得与余心会，野水黏天一片鸥。"]},{"t":"和李参政龙鹤庵庐二首 其一","f":"七言律诗","c":["落纸新诗万口传，逍遥旧梦记坡仙。","明虹短雨下平楚，老雁长云横半天。","涧底青松不改色，槛前流水谩安筌。","寄声多谢无名子，莫搅诗翁秃鬓眠。"]},{"t":"和杨仲禹送史子修特奏赴吏部注阙","f":"七言律诗","c":["科名宁较后先题，叹老嗟卑世所迷。","须识是閒天地似，要知立处圣贤齐。","人情一理涂涂附，古道千年印印泥。","属子随时崇令德，窗前红日未全西。"]},{"t":"和杨尚书韵送蔺恭甫归永康","f":"七言律诗","c":["梦绕秦祠月半棱，归寻岷岭雪千层。","傥来富贵垤藏蚁，尽大科名笔误蝇。","须验家庭真事业，更追简册淡交朋。","他年再出为时用，莫遣功夫似不曾。"]},{"t":"和范少才咏雪 其三","f":"五言律诗","c":["寒阴彫草木，枯叶委庭阑。","苍耸孤松秀，青敷万竹蟠。","封条才贴妥，见睍复攲宽。","但使根长在，毋忧风哭酸。"]},{"t":"和范少才咏雪 其二","f":"五言律诗","c":["随踏晓岩去，殿头金井阑。","路门圭璧委，双阙绛青蟠。","拜手朝绅肃，忧心旰食宽。","岁糜今有望，宁复厌菹酸。"]},{"t":"和范少才咏雪 其一","f":"五言律诗","c":["底处呼滕六，催将岁事阑。","窗明朝采烂，枝瘦夜光蟠。","炫晃山林老，模糊天地宽。","晓琴弦欲折，难忍溧阳酸。"]},{"t":"和胡秘书学中释奠","f":"五言律诗","c":["祠官环邃殿，晰燎向晨光。","工有歌咸夏，人无问国庠。","豆笾陈吉飨，磬管奏和锵。","盛事留篇什，赓酬愧不扬。"]},{"t":"和除夕前一日南叔兄会杨仲博杨季穆诗","f":"七言律诗","c":["玄里探幽识罔冥，易中观象见文明。","心虚有友皆三益，宇静无时不四并。","物理玩来成独笑，年华见惯渐忘惊。","只馀亲友关天分，离合钟情不肯平。"]},{"t":"和崔侍郎送行诗韵 其一","f":"五言律诗","c":["昔岁阽危日，烦公疋马来。","人心成胜势，天理是良媒。","抖擞精神集，扶持气脉回。","黄宫才一点，有许到葭灰。"]},{"t":"和崔侍郎送行诗韵 其二","f":"五言律诗","c":["轧轧度空明，怀人梦不成。","蜀天随处见，卮酒与谁倾。","多事鬓毛改，长途髀肉生。","随流浑未定，鼻息满船鸣。"]},{"t":"和蒋成甫见贻生日韵 其二","f":"七言律诗","c":["尚记春风酒满衣，数旬客馆掩空扉。","双乌念哺归难忍，断雁辞行凝不飞。","正念县弧成底事，有来连锦烂生辉。","亟哦七字酬佳赠，归棹潇湘水正肥。"]},{"t":"和蒋成甫见贻生日韵 其一","f":"七言律诗","c":["窗外浮云捲帝青，腰閒流水卧青萍。","发挥孔孟真三代，补葺嬴刘破六经。","理义本心如皦日，词章末伎谩流萤。","独嗟弱步跻长阪，百岁期程过五亭。"]},{"t":"和夔漕王韵 其二","f":"七言律诗","c":["成都别酒几何年，再见江漘岂偶然。","胡不握兰居紫界，却来转粟上青天。","鹏图海澨骞新味，雁断衡阳感旧联。","国子先生书在笥，愿从熟路力加鞭。"]},{"t":"和夔漕王韵 其一","f":"七言律诗","c":["开济堂前送棹歌，渊渊船鼓伐灵鼍。","云埋白帝千山小，浪拍青天一叶过。","解后天涯惊易别，顾瞻水剂得如何。","惟馀报国忠肝在，铁石云坚尚可磨。"]},{"t":"建士施霆亨自夔以诗相迓","f":"七言律诗","c":["三峡云连白帝城，风波九死得馀生。","虎头狼尾乱流济，猫面马肝缘壁行。","中衍何妨需在险，心亨但见坎常平。","况逢诗友慇勤问，宁复穷途哭步兵。"]},{"t":"武康主簿吴挽诗","f":"五言律诗","c":["羯末誇群从，凝徽肖一之。","风花摇切梦，梅雪照诗脾。","日短乌声急，天寒雁影悲。","广轮高隐地，千古一涟洏。"]},{"t":"知广安军勾侯挽诗","f":"五言律诗","c":["突兀双楠树，翘枝照户青。","春风吹湑湑，秋雨立亭亭。","蚁梦迷符竹，牛涔兀屏篂。","但令根本在，有茁媚阶庭。"]},{"t":"知合州赵侯挽诗","f":"五言律诗","c":["悃愊古循吏，宽和乡善人。","鸾宫六老会，月墅四时春。","转眼园松老，惊心宰木新。","来迟伤杜牧，宾主总成尘。"]},{"t":"知叙州史侯挽诗","f":"五言律诗","c":["便乘龙岁去，吾党果何观。","春味注眉睫，秋河悬舌端。","仁心随处见，民事切身看。","十载升堂梦，阶庭茁紫兰。"]},{"t":"知崇庆府致政何君挽诗 其二","f":"五言律诗","c":["不把英雄彀，移为仕进媒。","邑獒群怪吠，灶婢亦惊猜。","且效功成退，宁须兴尽回。","芸芸终有谢，赢得早归来。"]},{"t":"知崇庆府致政何君挽诗 其一","f":"五言律诗","c":["外监名父子，元方难弟兄。","鹤空黄壤梦，雁续紫霄声。","山远玉无胫，春多天有情。","至今溪上月，犹傍碧梧明。"]},{"t":"罗承事挽诗","f":"七言律诗","c":["人为浮名若挂钩，夫君知命独休休。","寒乌落日风林晚，老雁长云夜壑秋。","宝剑装留松影里，黄金籯在架签头。","便随丹旐堂堂去，宰木号寒起伏牛。"]},{"t":"罗监庙挽诗","f":"七言律诗","c":["春风擢擢秀阶庭，岁晚悠然物外身。","不把簪缨伤野趣，肯迂剑骑拂天真。","种成坟上一枝桂，空老堂前百岁椿。","乡里善人今已矣，龙门送客一酸辛。"]},{"t":"茂叔兄还乡北郊酌别","f":"五言律诗","c":["动是三年别，才堪十日留。","苍头相与并，软语未能休。","祇搅逍遥梦，真成浪泊游。","相期各努力，岁月鬓边遒。"]},{"t":"范圣问之母孺人史氏挽诗","f":"五言律诗","c":["是中无一物，快活不容言。","以此行州里，留之遗子孙。","寒泉鸿雁影，落日凤皇原。","三复幽堂志，夫人不死存。"]},{"t":"鱼耶孙氏挽诗","f":"五言律诗","c":["可堪风撼木，不见雪盈簪。","嫠纬愁春昼，儿书课夜深。","米盐毋我累，茕独是予心。","未报熊丸苦，寒堂服已廞。"]},{"t":"临邛张夫人之葬某既先事为之识竁今日月有时而某俨在衰绖义不获往吊又不能为文以侑虞殡命儿冲代赋","f":"七言律诗","c":["殗叶重葩两大门，只凭道义世昏姻。","养成气质槐为芷，发见仪容竹有筠。","自是子能为国士，何须女必嫁官人。","世衰俗薄昏成市，三复碑铭愤满巾。"]},{"t":"前利路运判冲佑李君挽诗 其二","f":"五言律诗","c":["从橐心知旧，枢庭肺腑亲。","不从呼尔食，宁独曳其轮。","吴子杰魁士，黄公忠荩臣。","所知非所厚，亦足验为人。"]},{"t":"前利路运判冲佑李君挽诗 其一","f":"五言律诗","c":["笃谨宁违俗，清淳不近名。","几多岐上泣，独自吉中行。","岁晚露沾草，山空霜满荆。","南溪后月夜，的的为谁明。"]},{"t":"南郊祖帐赋五十六言呈刘左史","f":"七言律诗","c":["绿水青畦泼眼明，红英翠柏伴将迎。","春怀拍拍浑无极，王事匆匆苦有程。","迅驿星驰惊客梦，白袍鹄立唤人行。","所嗟文物寥寥甚，况忍同时别两卿。"]},{"t":"叙州弟挽诗 其一","f":"五言律诗","c":["与女为兄弟，前年五十年。","并驱骖接革，偕立雁羞肩。","此意春融泄，中年俗纠缠。","每期身蚤退，白首对床眠。"]},{"t":"叙州弟挽诗 其二","f":"五言律诗","c":["祸我天何酷，子归自古诚。","女孥俄别父，宗直亦辞兄。","家难已稠叠，寇氛方满盈。","分明天有眼，不照此时情。"]},{"t":"叙州弟挽诗 其三","f":"五言律诗","c":["人物寂寥甚，天心分付谁。","禦戎伤畜缩，讲学病支离。","吏横民重足，时危命一丝。","若人天亦靳，抚事转伤悲。"]},{"t":"尝为赵太社作章泉二字及匹纸写诗二十二首赵一再有诗因次韵 其一","f":"七言律诗","c":["易象于坤必有章，泉翁此义发天光。","离趋外卦文加质，乾伏中爻絅覆裳。","欲验吾心观习坎，诚知是理识归藏。","公诗谢我祗成辱，敢复从公质寸长。"]},{"t":"度周卿之母蹇太宜人挽诗","f":"七言律诗","c":["八十三年雪桧身，直将簪珥当冠巾。","生儿须拟范孟博，论士亦知程伯醇。","在约能令家有塾，居閒肯使食无宾。","世间为母皆如此，扶值三纲不乏人。"]},{"t":"某曩在遂宁尝赋木犀云茂树幽花兀老苍不随众卉入词场虎头点点开金粟犀首累累佩印章明月上时疑白傅清风度处看黄香人才生世元如此不为无人不肯芳今十数年矣偶忆前作未免儿戏用韵再赋呈诸友","f":"七言律诗","c":["洞烟溪月楚山苍，万木辞林稼涤场。","老桂挟秋清入骨，明河倚树烂成章。","城隅静女閒逾美，泽畔累臣晚更香。","若数秋花饶此品，未容陶菊逞孤芳。"]},{"t":"费华文挽诗 其二","f":"五言律诗","c":["三凤齐飞日，相期到白头。","一丘生处乐，万事死前休。","风急啼乌夜，霜零断雁秋。","怀人竟何极，缄泪寄西州。"]},{"t":"费华文挽诗 其一","f":"五言律诗","c":["谨厚传燕国，宽和似蜀公。","材猷今世楷，论建古人风。","阅世心犹壮，忧时鬓已翁。","芸芸今有尽，归去得全终。"]},{"t":"费参政挽诗 其三","f":"五言律诗","c":["曲突有危虑，扣阍无隐情。","挥戈群啄害，断鞅一精诚。","斩错终何补，征辽祸已成。","惟公独知我，劝主不言兵。"]},{"t":"费参政挽诗 其一","f":"五言律诗","c":["鼎鼐谁无宅，人间昼锦难。","秋风三径老，夜雨两峰寒。","有志时看剑，无心晚据鞍。","行藏付千载，反覆要人看。"]},{"t":"赴遂宁进士期集即席赋","f":"七言律诗","c":["聘币鸣驺选实才，辇输使者作行媒。","般添春意和毡墨，嗺送花风上翠桅。","世论且然聊尔耳，诸君行矣勉之哉。","邦人此意毋虚辱，满贮香名万里回。"]},{"t":"赵广安挽诗 其一","f":"五言律诗","c":["蚤志周程学，期窥孔孟心。","人知行马贵，我爱隙驹阴。","秋树檠苍干，霜空耸翠岑。","一生迂事业，造物作知音。"]},{"t":"赵广安挽诗 其三","f":"五言律诗","c":["圭组曾分寄，经纶未究才。","冥心求己事，真气养玄胎。","月遽中河落，兰先白露摧。","若人嗟不淑，天意谓何哉。"]},{"t":"赵广安挽诗 其二","f":"五言律诗","c":["星陨南昌日，枭鸣蜀道时。","孝诚移地轴，忠泪洒天涯。","尽己皇它恤，求仁不复疑。","卫公精爽在，足尉九原思。"]},{"t":"赵德安挽诗","f":"七言律诗","c":["甲申露布告诛曦，丙戌巴台已磔禧。","或谓禄媭非汉患，谁知田李遗唐危。","安州得祸闻人说，荆莫上功惟我知。","三十三年旧寮友，朔风吹泪读残碑。"]},{"t":"送王教授之官临邛","f":"七言律诗","c":["剩喜人从义理趋，却忧末习堕浮虚。","未通经术先谈传，祇送人言不识渠。","偶向檐头觅桃李，径从纸上索鸢鱼。","君今去主师儒席，后倦先传谨在初。"]},{"t":"送刘类元奉对阙庭","f":"七言律诗","c":["突兀脩名磊磈胸，一鸣冠蜀未酬公。","十年解瑟无调瑟，百载张弓未弛弓。","剥啄门边谁主客，毕逋城上孰雌雄。","引吭为作朝阳瑞，携取香名寿乃翁。"]},{"t":"送李左史郊外和范泸州赠李韵","f":"七言律诗","c":["滔滔斯世果谁归，行止乖逢自四时。","桃李贪看炫春昼，菅麻谁解沤东池。","雨云翻覆人轻薄，旱暵艰难女仳离。","须信人生归去好，此行惟有雁行知。"]},{"t":"送李季允赴召 其一","f":"七言律诗","c":["拥马欢呼夹道迎，诏书洛社起耆英。","史筵载笔联翁季，政路题名接弟兄。","新政期公皆一律，故交惟我得忘情。","正邦须自明伦始，要仗公开万世程。"]},{"t":"送李季允赴召 其二","f":"七言律诗","c":["一倾鼎否一番新，但见新人笑故人。","元祐至今迭更化，崇宁以后几权臣。","曾趋嘉定改元诏，又贺端平第一春。","长把人才留一半，今年新是去年陈。"]},{"t":"送李季允赴召 其三","f":"七言律诗","c":["是是非非各有心，以同为爱异为憎。","誓殽秦穆旋修怨，在莒齐威卒震矜。","事急求言常易入，位高从谏最难能。","愿公一破从前陋，万里无云皎日升。"]},{"t":"送李梁山之官 其二","f":"五言律诗","c":["质行疑似钝，至论本亡奇。","一寸虚灵地，千年德政碑。","更穷山荦确，毋叹路逶迟。","官职时来作，天公自已知。"]},{"t":"送李梁山之官 其一","f":"五言律诗","c":["时论苦伊优，如君莫肯留。","乖逢惟有命，爵义不同谋。","且袖长年手，来乘浅水舟。","人间初水涨，一室自天游。"]},{"t":"送杨子有赴叙倅用高荣州韵","f":"七言律诗","c":["俗事萦人阻四并，东郊又送屏星行。","欲安边圉元无策，善服人心只有清。","使马如羊非我爱，带牛佩犊岂其情。","非惟此意行夷狄，谗舌虽工亦绝声。"]},{"t":"送赵茶马东归","f":"七言律诗","c":["又因送客朝京阙，意行偶过山之阳。","槛开岷岭半天雪，帘捲峨眉千丈冈。","断霞明空暮江白，密阴藏雨秋原香。","客归便可报明主，满川看看粳云黄。"]},{"t":"送唐述之赴廷对","f":"七言律诗","c":["快着青冥软玉鞭，稳骑騄耳踏云烟。","便持全蜀无双誉，去听宾胪第一传。","众所望君皆尔耳，人之好我岂云然。","古来名下无虚士，试玩盈科放海篇。"]},{"t":"唐昌文挽诗","f":"七言律诗","c":["重葩殗叶露华浓，不忝家声得似公。","休息生灵牙颊里，转移事变笑谭中。","却将仕宦四千石，换取宽閒五百弓。","岁路今归仙寿里，春来原上纸钱风。"]},{"t":"家承事挽诗","f":"五言律诗","c":["昆火玉孚尹，乔松冬夏青。","尘沙吹海立，风月半窗醒。","适意问芒屩，无心待屏星。","风流那复见，食报在宁馨。"]},{"t":"家涪陵挽诗","f":"五言律诗","c":["闻风唐御史，得意古周官。","治郡当如霸，閒居略似潘。","慈庭春后寂，书幌夜深寒。","漫有一区宅，传家地自宽。"]},{"t":"恭挽宁宗皇帝 其二","f":"五言律诗","c":["玉册宗昭考，宁王德比纯。","宫庭天事业，庙室祖精神。","遣奠俄廞马，书言痛获麟。","人穷天亦戚，雨雪故连春。"]},{"t":"恭挽宁宗皇帝 其一","f":"五言律诗","c":["内禅踰三甲，中兴会百年。","归疆才汶上，勒石未燕然。","忽怅龙髯堕，旋瞻燕翼传。","遗民满关洛，南望涕萦涟。"]},{"t":"海潮院领客观梅","f":"七言律诗","c":["竹外蒲牢挂晚晴，霜威洗出月精神。","山无此客林泉活，诗到兹游景气新。","元是当年郪县北，不知几度梓州春。","梅边认得真消息，往古来今一屈伸。"]},{"t":"致政宋君挽诗","f":"七言律诗","c":["窗寒研冷一生酸，坎止流行百念宽。","剑骑已荒江北草，简编归伴室中兰。","孰痴孰觉从渠看，真是真非只我观。","掩泪方相人已矣，广平遗录仅留残。"]},{"t":"袁侍郎挽诗 其一","f":"五言律诗","c":["学术趋平实，年来似寂寥。","岂无先后觉，未在始终条。","此老能深造，诸公独后彫。","平生寄心事，髣髴见鱼朝。"]},{"t":"袁参政挽诗 其一","f":"五言律诗","c":["奕奕万夫望，才名四十霜。","重来陪讲幄，三入位文昌。","地辟南厅峻，砖重首折行。","脩途日未旰，弭节复相羊。"]},{"t":"袁参政挽诗 其三","f":"五言律诗","c":["生世恨不蚤，庚申始识公。","象衣垂綷䌨，长佩奏璁珑。","幸甚蝇依骥，居然燕背鸿。","灵輀送无路，泪洒霅溪风。"]},{"t":"袁参政挽诗 其二","f":"五言律诗","c":["耆旧晨星似，公胡不慭留。","竟成青坞去，莫返赤松游。","时事方攲枕，天年不到头。","独馀经在笥，衮衮付公侯。"]},{"t":"通直郎史君挽诗","f":"五言律诗","c":["亹亹南陔意，孜孜北学宗。","片言销巧诋，三语剧崇墉。","正喜云随步，俄惊日下舂。","楼前半轮月，依旧挂长松。"]},{"t":"通泉李君以廷试卷漏结涂注自三甲降末甲赋诗以送其归","f":"七言律诗","c":["士为浮名若挂钩，夫君心事独休休。","阙书不害为全马，误笔何妨作牸牛。","少铁赢铜閒计较，着蓑衣锦等风流。","世间自有真轻重，归把功夫向里求。"]},{"t":"通直致政姚君挽诗","f":"五言律诗","c":["一生官偪仄，几处狱平反。","夜雨滴归思，凯风唳泪痕。","竟令驹入梦，莫尽桂销冤。","点检慈恩旧，秋空几断魂。"]},{"t":"郭孺人挽诗","f":"七言律诗","c":["一性根原匪自今，厥生异甚理难寻。","因思出腹恩难称，不恤伤肤念极深。","雷殷饥肠旋敛蛰，春温好语解移阴。","华堂命服蕃孙子，天报还渠一片心。"]},{"t":"高公权之母郭氏挽诗","f":"五言律诗","c":["妇道始衷终，宁过三者从。","髧髦维我特，蓬首为谁容。","但识同心处，宁拘异域封。","坛前两溪水，昼夜自溶溶。"]},{"t":"高开国挽诗","f":"七言律诗","c":["并游英俊半归泉，何事夫君又弱焉。","廉退风标留万口，勤劳心事入尘编。","团团故步八千石，落落浮名四十年。","除却江东肤使在，一时旧话向谁传。"]},{"t":"高承事挽诗","f":"五言律诗","c":["长身拘矮屋，雅志压华颠。","已矣宁非命，猗其尚有传。","饱餐广文饭，不击陆侯鲜。","惜也文明县，耆英欠此贤。"]},{"t":"寄题李季衡东楼","f":"七言律诗","c":["前年呼舫下玻瓈，突兀新楼闯目围。","雁影已随流水去，鹤归空感昔人非。","曩游历历梦中似，往事茫茫知者稀。","幸有季衡风味肖，何当倚槛语朝晖。"]},{"t":"崇庆通判杨君挽诗","f":"七言律诗","c":["长佩高冠集翠裾，华途落落仅题舆。","官无小大皆行己，理有是非宁问渠。","赋似长杨犹悔作，材如雄剑独藏馀。","方相掩泪催归去，遗稿空存子政书。"]},{"t":"教授致政李君挽诗","f":"五言律诗","c":["冠盖任云浮，门前日夜流。","不为盱豫悔，肯作浚恒羞。","科第联五叶，诗书閒一丘。","芸芸终有谢，赢得早归休。"]},{"t":"领客汎西湖客赋诗次韵","f":"七言律诗","c":["鸣鞘踏月大堤长，鼓枻穿云落日黄。","十里青漪菱草荡，四山红雨杏花冈。","客从民气觇春事，人在枝头看艳阳。","长使舟平风色好，世间何处有羊肠。"]},{"t":"黄夫人之葬某新有丧不得为文以侑虞殡命儿冲代赋","f":"七言律诗","c":["夫人心事与天谋，钱镈功夫岁晚收。","秸鞠声中春满羽，毕逋枝里月横秋。","将雏欲上空回首，食蔗才甘不到头。","况是我翁方念母，两乡风雨一般愁。"]},{"t":"曾少卿约饮即席赋","f":"七言律诗","c":["深院帘旌昼掩门，海牛挂出好乾坤。","日烘花影涨春腻，风撼柳丝明醉痕。","极目剪来齐翠嶂，关心看不断青原。","明朝又逐文书去，且尽今宵极意论。"]},{"t":"游上天竺","f":"五言律诗","c":["风波满平地，世路绕羊肠。","急欲逃尘网，遥登选佛场。","云深午犹暝，竹密夏生凉。","兴逸忘归去，高眠借石床。"]},{"t":"游监丞挽诗 其二","f":"五言律诗","c":["冰至人犹玩，波颓力不支。","摇摇路旁梗，炯炯日中葵。","学道长身健，忧时两鬓丝。","竟摇天老眼，畀以宁馨儿。"]},{"t":"游监丞挽诗 其一","f":"五言律诗","c":["论激回天力，身开夹日勋。","危言起平勃，奸胆落伾文。","泪洒衡山月，神凄蜀岭云。","若微刘柱史，千古閟清芬。"]},{"t":"程节推挽诗","f":"七言律诗","c":["入官当是学优时，政学尤知念昨非。","釜实剖争真识变，宝刀佩信解知几。","人谋是处虽同好，天理当然识者希。","易箦遗言无一愧，死能如此庶全归。"]},{"t":"程隐君挽诗","f":"五言律诗","c":["岁凶瓶粟罄，屋破褚衣单。","地寂鸟乌乐，天高鸿雁寒。","坟前晚生桂，露下草摧兰。","只把存耕处，令人反覆看。"]},{"t":"腊日同舍郎即湖上送诸葛吏部赴湖北常平次汪吏部韵","f":"五言律诗","c":["绣衣衔命去，祖帐为王留。","大舶满青镜，寒云明玉舟。","岁馀官事省，蜡毕吏功休。","千古行藏意，梅边细讲求。"]},{"t":"董侍郎生日 其三","f":"七言律诗","c":["潞公曩自蜀遄归，约仅踰年秉政机。","当日燕毛谁与并，后来接踵未应稀。","从星元合陪天柱，戴气宁当远日畿。","会看传宣燕私第，赐香成雾綵成围。"]},{"t":"董侍郎生日 其二","f":"七言律诗","c":["上到青天更上头，好风满地水连畴。","云开玉斧河边戍，月照金牛峡外秋。","举目河山无尽藏，关心筹略最高楼。","辛夷花下乌塘曲，未许夫公忆旧游。"]},{"t":"董侍郎生日 其一","f":"七言律诗","c":["紫气飞骞一马骢，当年轻下五云东。","诗书意味江都相，琴鹤规模清献公。","长啸驱风静秋戍，精神唤雨作年丰。","列城香火知何限，蒸起祥云入颊红。"]},{"t":"赐冠帔杨氏挽诗 其一","f":"五言律诗","c":["宾筵笾秩秩，宗室被祁祁。","琴瑟鸡鸣御，山河象服宜。","六珈不偕老，两髧誓维仪。","一代贤公子，堂堂锁穗帷。"]},{"t":"赐冠帔杨氏挽诗 其二","f":"五言律诗","c":["严霜六月降，老干四时春。","事阅三朝旧，年开九秩新。","母孙相与命，辈行独斯人。","蹇我幽忧久，伤心倍等伦。"]},{"t":"遂宁家知府生日 其二","f":"七言律诗","c":["相去无多五日间，两家牛酒贺生贤。","二阳引类临爻长，三寿为朋泰茹连。","析木旁瞻星两两，大椿遥祝岁千千。","相期协力亨屯难，未听丝丝鬓发宣。"]},{"t":"遂宁家知府生日 其一","f":"七言律诗","c":["玉堂元不閟英灵，地主还从此地生。","千里楼高人独立，九宗山峙月双清。","洋洋水薤临民意，猎猎霜林战叶声。","如许高情谁与拟，玉梅枝外看参横。"]},{"t":"雅州教授杜君挽诗","f":"七言律诗","c":["衣冠不但数城南，百世诗书味孔甘。","夜半辞金知畏四，璞中有玉刖宁三。","宦情本与秋俱薄，旅梦每惊春未酣。","已矣参军谁喜愠，一陂绿水镇涵涵。"]},{"t":"韩圣问挽诗","f":"五言律诗","c":["蜡貌宁违俗，规行不竞时。","苦思头没膝，勤诵涕垂颐。","州县频劝驾，藩方尝俛眉。","飘零竟何益，风雨脊令枝。"]},{"t":"鲁提干以诗惠分茶椀用韵为谢","f":"七言律诗","c":["秃尽春窗千兔毫，形容不尽意陶陶。","可人两椀春风焙，涤我三升玉色醪。","铜叶分花春意闹，银瓶发乳雨声高。","试呼陶妓平章看，正恐红绡未足褒。"]},{"t":"新繁县禾登九穗嘉甫弟有诗索和","f":"七言律诗","c":["长官真是委边嵬，积累如山姓里来。","认得两閒无二本，只将一念贯三材。","异形所感犹如此，同气相孚亦信哉。","陆续功夫宁有己，相期更验漆雕开。"]},{"t":"虞万州生日 其一","f":"七言律诗","c":["玉湖面面碧回环，六月寒飙撼屋山。","跨鹤不随刀梦去，卧龙甘与壁梭閒。","渔樵是处便争席，利欲年来早闭关。","拂拭石君勤把酒，照人风节两孱颜。"]},{"t":"虞万州生日 其二","f":"七言律诗","c":["沧江深处汲难浑，世味浓枯不见痕。","竹影移枰风澹荡，芰荷摇艇月黄昏。","坎离合处灵根峙，剥复机中硕果存。","门地人才如许秀，可能投老钓鱼村。"]},{"t":"虞万州生日 其三","f":"七言律诗","c":["初度相望十日期，一尊无路扣江扉。","羁人职事门重键，堆案文书山四围。","未办五千馀卷读，空惭三十九年非。","遥思道义宾朋集，梦作沧江鸥鹭飞。"]},{"t":"虞万州妻赵安人挽诗 其二","f":"五言律诗","c":["江上有何乐，萧然吾亦忘。","午眠春寂历，晚步水沧浪。","倦去推门入，忺来索酒尝。","清风那复见，江阔莫云长。"]},{"t":"虞万州妻赵安人挽诗 其一","f":"五言律诗","c":["妇言加妇德，公子嫁公孙。","澹泊于心慊，纷华入耳烦。","晋秦称匹国，韩姞烂盈门。","乃与其夫子，十年江上村。"]},{"t":"嘉兴张寺丞挽诗","f":"五言律诗","c":["壮气凛横秋，如何老作州。","有儿官左墄，无地办菟裘。","木落湖阴暝，书沈塞外秋。","佳城千古恨，树静晚风遒。"]},{"t":"嘉甫弟生日","f":"七言律诗","c":["山居面面接青天，更把青天触处看。","心事和平官职耐，家人顺正室庐宽。","栽培桃李扶春意，长养松篁伴岁寒。","门户千钧今付汝，书来时寄我平安。"]},{"t":"嘉泰二年题资州醮坛山星斗阁至是同王资州贾大安杨季持诸公登山用前韵 其二","f":"七言律诗","c":["天磨团团任往还，莫将止处认兼山。","水归寒谷敛秋练，木落前峰明晓鬟。","天度已归参井后，日行又值斗箕间。","若知此处真消息，血气浮名总是閒。"]},{"t":"嘉泰二年题资州醮坛山星斗阁至是同王资州贾大安杨季持诸公登山用前韵 其一","f":"七言律诗","c":["三十三年去复还，笋将重踏旧江山。","青衿朋友子当户，绿帻奚臧霜半鬟。","赢得光阴归鬓里，悔将声誉落人间。","圣门事业无穷已，只问君王觅退閒。"]},{"t":"蔡推官","f":"七言律诗","c":["人生宇宙皆同气，况此根心贯一机。","安用有生衔父恤，只愁无德报春辉。","桂芳春老伤何及，树静风号愿竟违。","更恨母慈临诀日，嗟嗟季役未成归。"]},{"t":"谯申甫惠诗有随缘婚嫁之语因次韵赞之","f":"七言律诗","c":["几见三星挂屋荣，人生难得是青春。","已惊梅实盈筐筥，方待河鲂下钓纶。","乃事未能超俗见，感时宁不念天伦。","随缘婚嫁君言是，且把乖逢付大钧。"]},{"t":"樊仲恂母太硕人李氏挽诗","f":"七言律诗","c":["梁君遁世偕妻孟，崔母祈天为妇唐。","身是六朝人物旧，眼看三世子孙昌。","人知翕翕味方隽，谁识耽耽意最长。","犹恨年龄不满百，仅成三万五千场。"]},{"t":"潼川孙监税挽诗","f":"五言律诗","c":["平地九折坂，通天一片心。","宁甘门肮脏，不与俗浮沉。","方授纵横对，忍闻虞殡音。","平都秋月白，精爽伴王阴。"]},{"t":"潼川路施运判生日 其一","f":"七言律诗","c":["家声烨烨自乾淳，王谢门中着此身。","金碧池边金碧使，玉山台上玉山人。","都将奕叶芝兰味，散作群州桃李春。","应记西陵分首后，枯棋一局几回新。"]},{"t":"潼川路施运判生日 其二","f":"七言律诗","c":["朔吹饕寒凝不禁，地雷应合战群阴。","悠悠未快功名手，渺渺谁觇造物心。","三寿作朋刚已复，二阳初动卦为临。","经纶及此身强健，插颔青丝雪未侵。"]},{"t":"题王巴州传经楼","f":"七言律诗","c":["牣庋充厨书满家，到无言处柰书何。","六经文字未曾有，三代圣贤如许多。","直自语言空布满，却嗟人物转消磨。","有来订古谈经者，试把斯言为切磋。"]},{"t":"题石洞","f":"七言律诗","c":["跨涧飞虹入洞门，石梯级级树森森。","两崖对立自宾主，一水长流无古今。","仙子吹笙招鹤舞，骚人得句伴猿吟。","个中便是蓬莱境，何必迢迢海上寻。"]},{"t":"题成都宪江公廉勤谨忠信和缓八箴","f":"词","c":["勤似忉忉廉揭揭，谨疑??信悾悾。","佩韦董子柔成缓，专瑟梁丘和近同。","义利只差丝杪忽，功夫端验始衷终。","六箴须把公忠贯，公处还归一字忠。"]},{"t":"题牟节叟介寿堂和刘左史韵","f":"七言律诗","c":["儿大诗书敌富强，妇供滫瀡养尊章。","照盘晓日龙为炙，介寿春风玉作堂。","礼物皆由天赋分，家荣亦使里生光。","人生有子不翅足，况复孙枝习气香。"]},{"t":"题李彭州南亭","f":"七言律诗","c":["花木精神面面全，谁将好景作南园。","栗留枝上春风思，鶗鴂声中晓屐痕。","檐外梅矾兄及弟，槛前竹鹤子生孙。","我今犹是数旬客，遇意忺时即打门。"]},{"t":"题南叔兄藏脩阁息游观","f":"七言律诗","c":["中存外习即藏脩，夙寤晨兴此息游。","要把孟轲三勿看，更将夫子四于求。","颜渊陋巷乐何事，曾晰风雩咏不休。","此意斯须不容离，敢申郑义儆悠悠。"]},{"t":"题洪崖安道人坟庵","f":"七言律诗","c":["当年过我两安君，白酒黄鸡话夕曛。","藜杖看山头拍背，褒衣论事齿穿龈。","平生大面三间屋，客死洪崖数尺坟。","身后更无锥可寄，忍看断雁泊孤云。"]},{"t":"题桃源图","f":"七言律诗","c":["伏胜高堂书已出，窦公制氏乐犹传。","鲁生力破秦仪陋，商皓终扶汉鼎颠。","隐者宁无人礼义，武陵独匪我山川。","若将此地为真有，乱我彝伦六百年。"]},{"t":"题袁追远亭 其一","f":"七言律诗","c":["朱枣离离实已稀，白云閒傍陇头飞。","囝思郎罢那得见，父曰子行胡不归。","树静风号终莫待，桂芳椿老苦相违。","舍南舍北寻遗响，衰草寒烟夕照晞。"]},{"t":"题袁追远亭 其二","f":"七言律诗","c":["宝剑初期多击鲜，嗟嗟何及泪阑干。","美官孰与承颜乐，丰祀何如啜菽欢。","已矣亲容生死阔，要知好道始终难。","共惟出自期无忝，留作松楸久远看。"]},{"t":"题贾伯用大龙阡","f":"七言律诗","c":["积薪寝火汉公卿，烂额焦头城郭臣。","新沔精神开白日，三泉血泪湿初春。","旧闻撇难须男子，谁识先机有妇人。","添入开禧忠义传，拟将笄珥易冠巾。"]},{"t":"题梓潼庙","f":"七言律诗","c":["士生一世果何事，道丧千年不得传。","富贵熏天随手尽，词华盖世为人妍。","直将了了圣贤质，只办区区文字缘。","神为斯人扶正学，试教梦者一醒然。"]},{"t":"黎州安抚赵挽诗","f":"七言律诗","c":["不为软语混光尘，独把刚肠敌世纷。","读史功夫头没膝，疾时风论齿穿龈。","慈乌反哺终违志，断雁辞行不作群。","犹有宁馨传素业，为求佳传贲丘坟。"]},{"t":"燕孙节推","f":"七言律诗","c":["快着青冥软玉鞭，直骑騄耳踏云烟。","等閒礼乐三千字，酬答艰难十九年。","鼎甲声华今有继，政涂事业岂无传。","愿君更拓勋名地，重玩盈科放海篇。"]},{"t":"燕孙节推致语口号","f":"七言律诗","c":["身是书楼东眷孙，老仙况复种仙根。","高科恰是承先躅，盛事还应表里门。","堂上承颜情最乐，窗前草制梦犹存。","着鞭且向长安道，春色如今紫诏温。"]},{"t":"燕新进士","f":"七言律诗","c":["已办书生场屋缘，枫宸入对字三千。","玉阶喜得方寸地，屋漏如临咫尺天。","学自孔颜期用世，道非尧舜莫陈前。","便听第一鸿胪唱，衣钵如余未足传。"]},{"t":"赠相士郭灏","f":"七言律诗","c":["载小奚奴长自随，两牛腰大赠行诗。","逢人有问辄如见，及我相遭不肯奇。","每会面时长好好，合开口处或期期。","道人莫是朱仙术，当与余言未及之。"]},{"t":"孺人谯氏挽诗","f":"五言律诗","c":["门闾冰似清，谯女复苏甥。","幸有室家乐，宁无兄弟情。","灭鄫虽未忍，归卫不容行。","独殿诸昆后，鸾封贲九京。"]},{"t":"魏抚干挽诗","f":"五言律诗","c":["同姓又同升，知君莫我深。","磨人三寸铁，行己四知金。","雪柏擎苍干，霜钟振晓音。","若人今在否，抚事一沾襟。"]},{"t":"魏茶马生日 其一","f":"七言律诗","c":["南渡波流荡潏中，绍兴御史最清忠。","和戎二字排时论，用世诸孙尚祖风。","弹压峡江群啸静，指麾边市虏资空。","盛心未必荣三锡，且喜朝廷答有功。"]},{"t":"魏茶马生日 其二","f":"七言律诗","c":["浪誇京洛渐尘清，局面今翻第几枰。","须倚玉龙擎重任，暂依金马作长城。","时人共记维寅度，阳画元从建亥生。","试向后天推八八，吾宗卜数万为盈。"]},{"t":"蟠鳌孙通直挽诗","f":"五言律诗","c":["趋义古君子，辞荣真丈夫。","泽车款段马，古锦小奚奴。","老树檠苍干，脩庭拥碧梧。","发潜无巨笔，斜月照龟趺。"]},{"t":"高龙学挽诗","f":"楚辞体","c":["蜀自开禧后，西垂畏廪秋。","更经两单阏，尽弃五边州。","新沔依同谷，中梁恃武休。","匆匆移米岭，往往阻金牛。","嶓冢略逋寇，益昌随解舟。","近犹趋剑阆，远或至渝涪。","弃守侪民旅，奔军齿寇雠。","乱生宁有豸，众溃已无鸠。","伯也伤时久，民兮作己忧。","升沈随分定，行止与天谋。","高尚辞丹诏，低回佐碧油。","封疆资屏翰，原隰赖咨诹。","事变方濡首，人情苦掉头。","誓言捐一死，力与障横流。","固分为忠鬼，安能效泣囚。","诀辞贻子弟，壮语骇朋俦。","愤极拳穿爪，兵交血染髅。","不随蜍志在，甘逐远巡游。","志士闻风起，顽夫背面羞。","公身无复憾，疆事更谁筹。","学士标龙直，文阶列禁游。","湛恩沾骨肉，新庙贲林丘。","三禭虽云厚，百身安足酬。","游魂如可作，近事亦知不。","惩败从娄敬，交邻激叛侯。","未论轻汉鼎，长恐误梁瓯。","后吏谁荓螫，前修不慭留。","玉棺行有日，丹旐送无由。","渺渺河山隔，皇皇兄弟求。","非惟在原急，亦为念宗周。"]},{"t":"丁大监文伯得余近作读之疾愈以诗见贻","f":"七言古诗","c":["黔巫之南溪水兹，山粗石恶不可治。","崇宁边臣务广地，山刊石断林木斯。","其间掌许号为郡，如以土偶安须眉。","中州人物犹此任，累臣舍是夫何词。","况于风气少疵疠，且幸习俗无浇漓。","饱餐贱米温旧读，书味隽永忘其疲。","坐看岁龙度丑戌，几见秋月弦虚危。","都梁有吏云端来，持书火急如符移。","美人家在九芙蓉，门墙突兀那可窥。","联缄累牍梦邪非，一年两度划见之。","我诗但能愈君疾，君解与世医狂痴。","乖逢休戚信有命，叹上不使非知医。"]},{"t":"七夕有赋","f":"七言古诗","c":["经星不动随天旋，枉被嘲谑千馀年。","无情文象岂此较，独嗟陋习轻相沿。","我尝作诗抵排之，尚有遗恨污陈编。","人于万物为至灵，聪明照彻天地先。","其如形气之所囿，则以学问开蒙颛。","不知谁为乞巧者，乃谓天孙执其权。","天孙能襄不能报，世閒之拙无加焉。","痴儿騃女竞针缕，高楼大第迷管弦。","汉魏以来用一律，无人出语扶其颠。","其间假拙济巧者，又欲托此文奸言。","敢因良会追往事，更发此义声馀冤。"]},{"t":"七夕南定楼饮同官","f":"七言古诗","c":["谁将明星贴天宇，州国宫垣象官府。","更将四七随天旋，常以昏中殷四序。","迢迢河汉冲秋旻，前有苍龙履玄武。","牵牛正向西南来，左右两旗北河鼓。","鼓星之侧为天桴，鼓上三星为织女。","何年人号天女孙，便把牛郎拟夫妇。","不知此是天关梁，河汉之津有常度。","晦明伏见莫非教，肯为文人给嘲侮。","班曹庾谢犹讆言，世上儿曹更堪数。","临风三诵大东诗，须信词章有今古。"]},{"t":"九日分韵得寒字","f":"五言古诗","c":["奇月必用重，谁与开其端。","贵阳而贱阴，于此亦可观。","况于五阴后，苍龙挂高寒。","林疏山骨瘦，宇静天容宽。","砉然遇九九，黄菊纷阑斑。","且开五言城，聊寄一夕欢。","凄其义熙后，甚矣天宝间。","陶社千古心，知者良独难。"]},{"t":"九月八日类试别所与同事饮而痁作","f":"七言律诗","c":["彼颛氏子太鸱张，药裹丹瓢为汝忙。","堆案文书埋白日，闭门风雨厄重阳。","酒尝友我胡为祟，菊亦愁余未肯黄。","閒玩群阴藏九九，花开身健竟须偿。"]},{"t":"八月七日被命上会稽沿途所历拙于省记为韵语以记之舟中马上随得随书不复叙次 其二十","f":"七言绝句","c":["风顺潮平日脚收，钱塘江上遇中秋。","堂堂背月争门入，要把平安报冕旒。"]},{"t":"八月七日被命上会稽沿途所历拙于省记为韵语以记之舟中马上随得随书不复叙次 其七","f":"七言绝句","c":["先从攒殿拜昭慈，尚想从容镇事机。","九十三年神驭邈，架椸犹是旧裳衣。"]},{"t":"八月七日被命上会稽沿途所历拙于省记为韵语以记之舟中马上随得随书不复叙次 其三","f":"七言绝句","c":["未到钱清四易舟，微躯兀兀任沈浮。","山阴境里平如练，一夜安眠到越州。"]},{"t":"八月十五日夜月意偃蹇夜久微明须臾复晦瞻叔兄有诗因次其韵","f":"七言律诗","c":["长风送月九霄宽，无赖浮云告亦顽。","本自无私长委照，不应有碍似偏悭。","苍生望治东山隐，四海倾风钓濑閒。","潜复虽深终是昭，停觞且待夜深还。"]},{"t":"十一月九日新滩李示余开禧三年四月九日所跋外舅杨宪使滩字韵诗为次韵","f":"七言律诗","c":["忆从筮仕岁涒滩，三十馀年阅暑寒。","抚事无成人潦倒，怀人有梦涕汍澜。","家山扰扰胶胶里，庙社嘻嘻出出间。","欲上青天愁险绝，谁能为我斩楼兰。"]},{"t":"十二月二十日领客登介亭分韵得梅字","f":"五言古诗","c":["晨镳载宾从，披雾陟崔嵬。","宇宙敛盈握，江湖大容杯。","孱颜石丈人，玉立山之隈。","山前大第宅，马头涨黄埃。","独此抱昭质，萧然侣寒梅。","有客以问余，豫为地为雷。","雷出地为奋，何取于石哉。","人以动为境，沄沄不知回。","而能介然存，神气斯有开。","相对得深省，欲归重徘徊。"]},{"t":"万杉寺","f":"七言绝句","c":["万杉深处着僧庐，中有昭陵飞帛书。","想象承平心似醉，小亭伫立看跳珠。"]},{"t":"上巳领客","f":"七言古诗","c":["流觞元巳奚所因，更指三日为良辰。","山阴坐上皆豪逸，长安水边多丽人。","临流有许豪与丽，元无一个能知津。","韩婴何凭指溱洧，束晰胡据诬周秦。","千年混混同一波，竞言此日天气新。","其间号曰该洽者，或言鳦降祠高辛。","春分以后弗无子，往往援引诗生民。","说虽有稽义犹凿，况复除日经无文。","予尝妄意巳为火，季春火见疑乘寅。","寅居汉津火所畏，故以元巳祓水滨。","一年奇月必用重，三三欲解阳德屯。","较之前说已云近，终愧俚俗疵吾醇。","要须挈我沂泗上，回瓢点瑟看长春。"]},{"t":"大理曾少卿欲见余近作录数篇寄之以诗为谢且云连日疮疡作读余文而愈因次其韵","f":"七言古诗","c":["西风萧萧吹鬓急，独立长空倚天壁。","俯看沧海环九州，仰视青云行白日。","夜归蟋蟀鸣秋床，触处万宝西风香。","而余生世竟何事，孔翠兹影蜉蝣裳。","冥心宴坐自探测，善利几微如白黑。","江西夫子最知心，欲往从之后土湿。","忽来诗句悬清风，拱揖孔孟麾瘠痈。","便思载酒巾车童，一夜壮气干星虹。"]},{"t":"子益教授再用韵赋弈有审机从谏之诲某复和呈 其三","f":"七言绝句","c":["才分虽殊学可能，譬如泰华立曾曾。","居高视广心逾远，下视群峰如豆镫。"]},{"t":"山河叹送刘左史归简州","f":"七言古诗","c":["山河两戒南北分，天地一气华戎钧。","譬诸指搐非害事，往往四体为不信。","惟今丑虏相噬吞，人言雪耻兹其辰。","盍驱卞庄刺斗虎，又嗾庐㹱擒狡㕙。","天王仁爱兼南北，犹遣升勺苏穷鳞。","诸公亦复创前误，闭户不肯顾斗邻。","流移降附莫皇恤，斩艾驱迫如穷麇。","谁知炎炎将及我，事体不与开禧伦。","竟因示弱启狄侮，羽书赤白惊严宸。","天王坐朝色不怡，我非尔畏民吾民。","急从雨中彻桑土，更向火后移突薪。","大官亦复变前说，群而和者非一人。","制书丁宁示招纳，符檄旁午申拊循。","臣某奉诏移江介，臣某董师留汉滨。","西南忧顾谁其宽，即授臣某留川秦。","夫何廷论忽中变，复议保境思和亲。","迅雷烈风仅翻覆，明虹霁日俄逡巡。","敌人揶揄胆满干，志士愤郁齿穿龈。","东由海泗尽襄汉，西起梁沔连房均。","暴骸蹀血蔽原谷，夺险因粮空窖囷。","将军忧恚或自毙，列校偃蹇不可驯。","县徵更赋不遗算，郡空少府无馀缗。","边头被兵甫属耳，公私已屈忧方新。","静惟人事百罔一，恃以亡恐惟苍旻。","苍旻茫茫君为度，但见咎异来相因。","连年夏旱天无云，江淮湖浙田生尘。","飞蝗排空如羽阵，噍类猥众何诜诜。","僰南山萃陵谷异，后土矹矹如转轮。","春秋二百四十载，地震才五兹何频。","去年东南复告旱，遍以牲币走百神。","太阳朔蚀忽无光，金星昼见亦累旬。","汉沔沸腾地移轴，涪潼湓溢涛翻银。","星文屡变台符坼，阴象较著阳德屯。","外为兵戈为裔夷，内为宫壸为群臣。","天心渝怒有如此，犹以谴告施其仁。","惧而修政庶可弭，恬不知警将仍臻。","且如前年旱蝗日，开道求谏颁明纶。","庭中不鸣自如故，犹有下位人姓陈。","内言椒房之舛令，外及丞相之狎宾。","能如章向触权忌，不效钦永攻上身。","同时六馆之髦彦，陈义固争尤肫肫。","藐如无闻亦异已，宰士忿疾丞相嗔。","彼唐畋铎何物耳，词鄙意佞如吠狺。","外省胡独行其言，公然贱玉而贵珉。","自时厥后益惩创，遏绝言路忘咨询。","直臣久矣甚弃梗，公道不迪随荒榛。","尝居丞疑转猜忌，稍负望实尤沈沦。","人心所同即天意，四方蹙蹙天亦颦。","公今掉头不肯住，携家归踏西园春。","大贤与国同休戚，宁忍赤子方嚬呻。","我非荷蒉不知磬，拟效执舆来问津。","请赋白驹之孕章，愿公饮酒车无巾。"]},{"t":"飞雪亭","f":"七言古诗","c":["自荆入蜀路险绝，墨猿声中胆欲折。","万州江头舍舟楫，又趣担簦穷岌嶪。","危磴连云如积铁，乱石砭足十九跌。","仆夫流汗马吐舌，遥望盘龙拄天胁。","悬瀑落岩喷霏屑，中间有亭曰飞雪。","十里阴风寒入发，人言此地无六月。","火云射地人不暍，谁知利欲所熏灼。","以身试险车结辙，伐性焚和火如烈。","试于此亭解羁绁，呼取大斗酌甘洁，一饮令君消内热。"]},{"t":"中秋无月分韵得狂字","f":"五言古诗","c":["金低辟老火，月琯行仲商。","是为阴之中，正与日相望。","浮云横相掩，人谓妒且狂。","彼云初无心，此月亦何伤。","水月本同体，其中根于阳。","炯炯含内景，随时发辉光。","天机之浅者，为人作閒忙。"]},{"t":"中秋有赋","f":"七言古诗","c":["望舒与日元非敌，震受阳光巽成魄。","六十四象不言月，三百五篇讥月出。","古道贵阳不贵阴，宾礼卜昼不卜夕。","世间赏玩起何年，误却千年醉狂客。","不知客有肺肠无，更把荒诬作真实。","我因时序尝作诗，洗尽兔窟蟾宫迷。","今年新作东楼成，胡为尚此穷攀跻。","人心和平民气乐，日月昭明天宇豁。","须知此事与政通，不是词人閒赏月。"]},{"t":"中秋领客","f":"五言古诗","c":["秋中无常期，月望无常历。","况于月之房，岁十有二集。","云胡三五夜，赏玩著今昔。","我观魏晋前，未有娱此夕。","岂由夕月礼，承讹变淫液。","天行至东北，阳升乃朝日。","日月向南来，三务趋朔易。","则于阴之反，顺时报阴魄。","古人敬天运，随处察消息。","俗学踵谬迷，更以儗科级。","广寒八万户，桂树五千尺。","文人同一辞，祇以惊俗客。","墨墨数百年，月如有冤色。","为作反骚吟，聊以补载籍。"]},{"t":"元夕卜油溪故事 其二","f":"七言绝句","c":["满目忧端膏火煎，聊将膏卜验新年。","只祈五色云瑞世，不愿蚩尤旗亘天。"]},{"t":"六月十四日后殿侍立新永康太守成嘉甫朝辞奏事词气恳恻上为嘉纳尝随笔纪其事今乡人祖帐分韵得西字遂书以赠行","f":"七言古诗","c":["严精伐鼓趋晨鸡，龙媒戒仗喑无嘶。","宰臣奏事左墄降，史臣曳履东阶跻。","永康太守臣申之，上殿音吐干虹蜺。","曰臣前领大农簿，试郡得请今当西。","鞑人求通反其使，金人匿壮招吾携。","勿言残金继前好，将贰鞑靼摇青齐。","时将有反事有间，玩岁愒日忧噬脐。","皇帝瞿然曰是是，伸颐颔首天听低。","贴黄更请磔叛将，褒恤死事不可稽。","陛下亦闻西事否，昔号险阻今多蹊。","散关皂郊已平地，白环黄牛犹溃堤。","分台列阃越秦视，体统涣散人情睽。","上云私意误大事，谆谆切切重提撕。","申之又言故臣丙，昔尝有德于坤倪。","上顾指臣曰安丙，申之顿首如含悽。","纷纷交情异生死，独此推本祛群迷。","臣时张拱立帝傍，螭头恨无千赫蹄。","为王留行力不足，戴目处此羞梁鹈。","宫无小大莫非事，勇为天子绥群黎。","天如有意听臣归，问天重乞青玻瓈。"]},{"t":"天台张氏兄弟挽诗","f":"七言律诗","c":["静将物理验良知，父母恩深报称微。","群动芸芸看夜息，万生点点发春辉。","错居宇宙犹同气，况此根心贯一机。","理道亶然人莫究，是家兄弟庶全归。"]},{"t":"王总领生日","f":"词","c":["古来五大不在边，国家长虑初解弦。","西南计臣授鈇钺，独以一手擎半天。","三边将士趋节制，百城吏民服威惠。","载宣宽诏问无恙，扶藜往听翁颜喜。","我图尔土居未怡，室家仅葺风雨欺。","波涛沄沄逐风靡，山色澹澹忧陵夷。","机空络纬那可织，徽穿虎豹畴能识。","秦门夕燧虽平安，燕帐秋弓未休息。","翁颜且喜旧观还，尚恐世事愁无端。","祝公为民久远虑，忧顾期使西南宽。","美官厚禄等閒耳，得君得时不易然。","君不见富公在青州，多于中令廿四年。"]},{"t":"王总领生日","f":"五言古诗","c":["皇天覆后土，藐然中为人。","职职万同宇，何所非吾仁。","一二指搐耳，动且关嚬呻。","置之非害事，尚欲求其信。","矧今我赤子，犬羊所噬吞。","养之将遗患，迫之几寡恩。","犹以赤子故，未忍穷追奔。","蠢彼不我德，羽书惊严宸。","帝曰斯可矣，戎首将自焚。","一军戍江介，一军留汉滨。","雨中彻桑土，火后忧突薪。","又念蜀上游，擢才饷吾军。","蜀力如蜗涎，仅足以濡身。","云胡走荆楚，坐视空川秦。","天下本一家，奚必尔我分。","独怜去天远，缓急呼不闻。","公今从此升，于国拟世臣。","家有忧民谱，切磋及兹辰。","直前明分义，却立思本根。","岂但无怨公，此志长光新。","抑使蜀父兄，寿公以峨岷。"]},{"t":"王常博寄示沌路七诗李肩吾用韵为予寿因次韵 其一","f":"七言绝句","c":["误随烟艇武陵溪，未见桃花路已迷。","云掩九扉风露冷，又吹残梦夕阳西。"]},{"t":"王常博寄示沌路七诗李肩吾用韵为予寿因次韵 其三","f":"七言绝句","c":["前村风日熟新粳，尚记来时带雨耕。","大化驱人人未喻，等閒文字过平生。"]},{"t":"兄子高赴廷对","f":"词","c":["九十九峰矗天起，家在前峰夕阳里。","蛮徭虎豹断行人，小市寒城净如水。","驩传有客闯然来，㩜衣视之吾兄子。","云从诸侯贡，往备天子使。","来时吾父为我言，女之靖州问安否。","靖州苦好脩，女从得师友。","世方白首声利场，父诏子承乃如此。","柳阴花影春风香，喜极无言澹相对。","家学既尔殊，天资亦云美。","自庵寂寥无可赠，赠以庵中一个自。","吾闻古之人，仕学皆为己。","上不可欺其君，下不忍虐其类。","此岂有为然，凡以自靖耳。","我之行止命于天，上下四方难豫拟。","旦将自靖献于君，无限功夫归语尔。"]},{"t":"出剑门后日履危径戏集轿兵方言","f":"五言古诗","c":["篮舆陟险隘，兀兀不停辙。","主人眩头目，仆夫困唇舌。","前疑树梢拂，后虑崖石擦。","方呼左畔跷，复叫右竿捺。","避碍牢挂肘，冲泥轻下脚。","或荆棘兜挂，或屋檐拐抹。","或踏高直上，或照下稳踏。","斯须有不审，偾舆在目睫。","深渊固可畏，平地尤险绝。","作诗告仆夫，审诸秋毫末。","识察既晓然，力行谨无忽。"]},{"t":"北郊劳农归路五十六言","f":"七言律诗","c":["方春不及与劭农，十月郊行劳岁功。","因记旱云占晻濭，更愁霖雨望曈眬。","田苗粒粒祈禳里，民命丝丝叹恨中。","忧国愿丰虽我志，更须人事与天通。"]},{"t":"史宜人挽诗","f":"五言律诗","c":["勉夫惟有义，为舅可无生。","不是多闻识，那知真重轻。","子从观处化，身在吉中行。","况复无馀憾，堂封勒蔡铭。"]},{"t":"四川茶马牛宝章修扬子墨池以书索题咏","f":"七言古诗","c":["子云一去千馀载，惟有成都墨池在。","草玄此地是邪非，玄文今在人谁知。","虽逃刘歆酱瓿阸，鼠壤蛛窠蠹鱼宅。","岂无学者工探求，不讥僣圣几赘疣。","自从马邵造玄域，晁氏谱之张氏翼。","亦云察矣人犹疑，试为诸老申其辞。","易书广大包天地，辞变象占都一致。","世儒造入各不同，有一于此均为功。","况于易玄互相发，不同之同真善学。","历家中首先黄钟，虽以坤复为初终。","纪日天正始牛宿，又以日星分左右。","起从冬至易玄均，玄意欲取臣承君。","易书八八而用七，玄文九九而存一。","易分六位中二五，臣志上通君下取。","玄以一五而为中，君道君尊臣代终。","玄文主日易主岁，易书为经玄为纬。","谓玄于易地承天，就中邵子尤知玄。","或云玄准卦气图，是图疑亦非圣书。","岂知中复与咸遇，乃是阴阳自然数。","或云玄仿太初历，黄钟之分八十一。","岂知虚三与虚九，其数虽同其法否。","或云玄象宗浑天，浑天方象包于圆。","岂知兼用盖天说，盖以舆地承纯乾。","易虽无玄不为阙，易更得玄滋有发。","且如河图与洛书，发挥道数无遗馀。","后来支干及声律，运气参同至太一。","与易并行人不讥，千岐万辙同一归。","况玄于易同而异，何独于玄苦讥议。","子云之师曰林闾，鹤山之下谁其徒。","自翻机杼作生活，律历图书无不合。","若非马邵晁张伦，后世几无扬子云。","后世子云今继作，而此玄文终寂寞。","空馀绘象与棠阴，聊与文士供嘲吟。"]},{"t":"四月二十日领客寻龙井前盟以雨阴晴未定不果往买舟下西湖步至玉泉观鱼分韵得东字","f":"五言古诗","c":["前期戒宾从，再候苏长公。","晨炊马亦秣，宿载车既董。","飞廉何方来，横出云半空。","便将龙井泉，换却西湖风。","公非閟清境，乃似开其逢。","烟柳夹大堤，拳荷点清穹。","水涵乱云白，露湿残照红。","不是我辈人，此味谁与同。","神閒等喧寂，意适无西东。","观鱼滋有发，归骑春风中。"]},{"t":"永嘉林君谊父得英石名其室曰矸斋予易以介室","f":"五言古诗","c":["柳侯谓楚南，多石而少人。","至今英道閒，异石何嶙峋。","乃知五行气，中土为秀民。","降才既匪易，自弃奚不仁。","伾文一日炎，乃以焚其身。","林君若知此，是石当书绅。"]},{"t":"生日和辛江陵即席韵 其一","f":"七言律诗","c":["有生同得本来公，凛凛渊冰保降衷。","多愧行年称有子，长怀当日谢无功。","羁踪不称歌三拜，浅量难堪酒一中。","饮尽玉瓶天地阔，不知身客楚台风。"]},{"t":"生朝李肩吾贻诗次韵为谢","f":"七言古诗","c":["肩吾作诗庆五十，矜我颠跻授之絷。","因思五十义最精，造化机缄斯出入。","君看五位相生成，前荡后摩如授揖。","至于五衍宜有穷，泽火趋新承井汲。","作圣工夫方自兹，为人生活知非急。","昔人于此叹始衰，血气虽衰义逾集。","蹇余不学晚知非，方把斯心验存蛰。","独嗟道远莫致之，愿与始终谋不及。"]},{"t":"用真景元韵题豫章朱正父湖山清隐诗卷","f":"七言律诗","c":["乾坤尔阔着吾庐，水绕山环仁知居。","君友东湖徐孺子，我闻西洛邵尧夫。","欲为天下屠龙手，肯读人閒非圣书。","聊借斯言相赠勉，乐颜之乐即颜徒。"]},{"t":"任宜人挽诗","f":"五言律诗","c":["家声门九戟，庭秀树三株。","阃范闲金燧，林风瑩玉壶。","未经亲绛幔，何遽作黄垆。","凝睇两竿竹，醇情一束刍。"]},{"t":"先立春一日电雷雪交作程叔运赋诗次韵","f":"七言古诗","c":["自从日驭行牵牛，四十五日为春朝。","谁驱阿香送劈历，更遣玉女来姑瑶。","从来雷雪不两立，有如皋禹于驩苗。","闯然方驾朝正月，是反常性皆为妖。","阳孳于子达于寅，蛰虫欲动寒鱼跳。","苍龙久移旧岁次，朱鸟亦向新年杓。","如何阳伏不能出，阴气所沴如沃焦。","相摩为电搏为震，始初隐隐如迢遥。","剨然一声到匕箸，惊魂忽忽不可招。","须臾为雹又为雪，寒威挟胜尤宣骄。","春秋已事且云远，绍兴狄难几难调。","乃今此异已累岁，卧制四海由衾裯。","徒令志士歌且谣，无人采寄观风轺。"]},{"t":"再次韵 其二","f":"七言绝句","c":["我尝妄意于古人，子今用力苦先我。","安得从容长似今，借子玉匙发关锁。"]},{"t":"再次韵 其一","f":"七言绝句","c":["眇观千载苦无人，窥见一毫先有我。","隽敏既为文采误，高明又被玄虚锁。"]},{"t":"再和浣花韵呈李彭州李参政","f":"五言古诗","c":["冁然一开口，天也非人谋。","江山自旧管，风景仍新收。","一门令兄弟，而我从之游。","卫玠珠玉侧，李膺神仙舟。","主宾有良晤，兄弟无相犹。","雨馀白日静，江远青天浮。","相彼宇宙广，觉我心休休。","世传浣溪女，声迹疑谬悠。","灵均亦已远，英烈今在不。","又怀唐拾遗，泯然哀江头。","陵谷几变迁，屈孟独长留。","于此本何负，而以德为雠。","因时慨前哲，坐久风飂飕。","良会惜难再，作诗以相酬。"]},{"t":"再赋","f":"五言古诗","c":["淘金乱川绿，发䓞烧山红。","自为天一隅，奚翅地十同。","米贱衣弗费，四民罕全功。","功夫到华卉，未至浇淳风。","老梅委林莽，洛佩遗丁东。","茶华新移根，脱命斤斧中。","焉知贲然者，秋毫皆苍穹。","观物弗之察，吾欲问黄熊。"]},{"t":"再韵","f":"七言古诗","c":["文华灭质甚尘土，物欲戕生剧豺虎。","三年挂舌坐林皋，日月往来云散聚。","夫容自与诗肠谋，虽无颜色媚涂陬。","梦随春草撩客儿，手抉云锦分潮州。","平生耻作山鸡照，对此忘其为不肖。","为华破戒哦七字，殆似五噫发梁耀。","李君不为掩覆之，唤取奚锦披封泥。","缫车引出万丝绪，衣被山谷春无辉。","山中华木迭宾送，人把荣枯同幻梦。","卧看夫容生未生，满目天机供日用。"]},{"t":"安大使生日","f":"七言古诗","c":["往年天压西南垂，妖氛内讧胡尘飞。","枭狐陆梁士扼腕，蜀山惨澹无光辉。","公以空弮婴乳虎，漠漠黄云闇平楚。","直将天理感人心，径斩贼头报明主。","露布东驰人啸呼，京师观者环储胥。","天颜有喜近臣贺，大官高爵来须臾。","中兴以来几变异，宗祏之存如旒缀。","平江羽檄走凶雏，采石鳅船戮狂猘。","至今勋名满华夷，与公鼎立书旂彝。","公方退然不自居，忧国之鬓纷如丝。","天之生公为社稷，南山不蹇石不泐。","愿公蚤归相天子，赤舄晨朝容几几。"]},{"t":"安大使生日","f":"五言古诗","c":["恭惟天祐宋，奕叶际明良。","积德由文武，生贤迈汉唐。","粤稽资殿老，降自皛山阳。","崧极申函粹，东维傅启祥。","堂堂三代直，赫赫万夫望。","清庙圭璋璧，明堂枫柞樟。","诏成来凤翥，云滃际龙骧。","谁误玄黄篚，争驰赤白囊。","搀枪星有耀，晻曀日无光。","白昼鸣枭獍，长衢纵虎狼。","公卿失匕箸，帷幄自金汤。","昔在齐刘豫，前睎石敬瑭。","久为虏臣妾，深入汉封疆。","谁似机筹妙，曾无矢镞伤。","边城长男女，农亩遂耕桑。","惠泽孚禽兽，威棱憺犬羊。","报勋隆爵秩，纪绩满旂常。","事业侔伊吕，功名陋霍张。","岩岩千仞壁，纳纳百川航。","经国般营室，忧民旅念乡。","直方坤立德，中正泰包荒。","天锡公难老，神扶福孔穰。","冲襟凝日谷，温语泻天潢。","寿域周三蜀，春祺遍一方。","蓬峦擎屃赑，壶玉扣鸳鸯。","御府颁殊玩，褒纶下十行。","绣鞍翻昱爚，茸纛立荧煌。","万古功名样，千年节义香。","九重新政理，二枋孰维纲。","当宁畴耆硕，非公莫便章。","白麻飏殿陛，金衮赴文昌。","会整乾坤了，长令海县康。","作经七六艺，致主四三王。","自顾蓬蒿质，敢希桃李场。","熊占祥入梦，駉颂寿如冈。","画地数勋烈，指心成激昂。","莫驰千里足，亲对九霞觞。","天汉江山美，中书日月长。","愿言崇令德，永作世津梁。"]},{"t":"次李肩吾送安恕父回长沙韵 其二","f":"七言绝句","c":["冰力方刚风助威，经旬足不到门畿。","可人安倩来相问，语极情生爵娄挥。"]},{"t":"次李肩吾送安恕父回长沙韵 其一","f":"七言绝句","c":["寒云苍惨跕鸢嘶，野水冥濛倦鹜飞。","茆被纸窗长失晓，愧曾日日侍宸闱。"]},{"t":"次程少逸饯杨叔禹教授","f":"七言律诗","c":["载酒时从执戟郎，雅知清望称鸳行。","肯来芹泮提英裁，要取芳编阅旧香。","玉倚蒹葭方借润，珠移甓社陡寒光。","临来莫恨车无角，疑睇云霄紫凤翔。"]},{"t":"次虞万州韵送曹简夫守宣城","f":"七言律诗","c":["膂力方刚发未翁，不令忧乐与民同。","卷人间事风尘表，收天下春襟府中。","江北勤劳谁念德，湖南干事未论功。","如今又听还家去，缓急分明要此公。"]},{"t":"次韵丁大监见怀 其二","f":"七言律诗","c":["见惯不惊如四时，流光任逐鬓蓬飞。","日从南去老龙蛰，火向西流玄鸟归。","荷子感时堂蟋蟀，移书劳我室伊威。","益嗟往日无良友，四十八年成一非。"]},{"t":"次韵九华叶见思鹤山书院诗","f":"七言律诗","c":["天空地迥托吾庐，何处山川不裕如。","太极光阴宁有閒，环中事业本无书。","道亨谁谓大人否，夷陋不妨君子居。","昨梦九芙蓉里去，起闻跫足到空虚。"]},{"t":"次韵史少庄竹醉日移竹 其一","f":"七言绝句","c":["艳艳洒妆斗姚魏，冥冥花影逢石丁。","醉生梦死何如竹，三百五十九日醒。"]},{"t":"次韵外舅杨崇庆以诗相招 其三","f":"七言绝句","c":["寄语荷郎且缓开，山中衣制要君裁。","不随褦襶触热去，待学山阴乘兴来。"]},{"t":"次韵外舅杨崇庆以诗相招 其一","f":"七言绝句","c":["炎威翕翕正鏖人，惟有西风不世情。","困卧小窗倦宾客，吹将好语到岩扃。"]},{"t":"次韵永平令江叔文鹤山书院落成诗","f":"七言古诗","c":["天运驱人人不觉，古道违时时不学。","王相随胫回荆山，昭质依然未经琢。","因思胥靡逢殷宗，精神动悟声气从。","砺舟霖雨到梅糵，变化气质天同功。","朝歌屠叟无与语，一日投纶见明主。","大车槛槛行周道，轮辐中规箱中矩。","人生天地同一原，自诚为圣明为贤。","地殊世远犹合节，矧此同宇相周旋。","自从浇风散遗直，世不乏材无匠石。","未能登车习射御，人人自视邮无恤。","出门浪战触与蛮，半生少得须臾间。","不为夷甫辱汝水，即似介甫逋钟山。","古人洒扫先庭户，岂问他人莫余顾。","只忧原头欠渟滀，才见天根便呈露。","人言阴浊胜阳清，阳一阴二分三亭。","谁知阳德本无间，根心枝叶长相亲。","君臣大分虽有止，终不能忘乃天理。","世无我知将自知，不待雷风问诸史。","投沙屈贾占所归，九州博大归何之。","虽云忠愤语伤激，律以洙泗犹津迷。","前村虎啸晚风起，跕鸢酸嘶雁将子。","君恩未报臣忧深，暇把壶头较乡里。","江公劝我姑少安，新诗肉好如璧环。","敢输忧诚谢庆语，仍戒牍史毋抄传。"]},{"t":"次韵刘左史王亭观梅","f":"五言古诗","c":["南山有佳境，天作而地藏。","谁其搜抉之，主者今欧阳。","时当冬候最，叆叇云无光。","烂嚼暗香句，浩歌黄竹章。","诗成物有主，意远天无旁。","众宾从老守，遥林拱孤芳。","气味自尔殊，凡卉不敢香。","芸芸天壤间，何草冬不黄。","独此冰雪质，老气磨苍苍。","便如身洁人，易知复难忘。","颇怀熙丰日，群妍偃冰霜。","皓然深衣老，春风贮肝肠。","抉开第一机，还作桃李乡。","终然和鼎实，以侑千岁觞。","三嗅几而作，临风倍轻狂。"]},{"t":"次韵西叔兄日食地震诗","f":"词","c":["正月太阳食，六月阴萋萋。","利沔阶成间，桑土为涂泥。","破山覆桥阁，灌城坏河堤。","蜀地五六震，积潦伤农畦。","梓州暑尤异，我兴看朝隮。","出逢七十翁，履敝衣无绨。","前行为余言，老夫齿含齯。","阅事亦已多，近闻何乖睽。","去年大官括隐户，父詈子诅妻悲啼。","大官深居那得闻，小吏鼻息干云蜺。","今年得少休，北风苦凄凄。","番军袭江淮，将士惊噬脐。","四方靡所寄，容身仅坤倪。","灾异又如此，宁保梁益西。","太守闻此言，惕如履征鼙。","又见广文诗，口呿心沈迷。","力能得为仅千里，滔滔四海皆馀黎。"]},{"t":"次韵庐陵刘时见怀","f":"五言古诗","c":["夬终伏剥果，畜极逢天衢。","否泰反其类，艮止与动俱。","此道固晓然，人情不同趋。","两目自安障，狂童为子都。","羁金络明月，骐骥旆疲驽。","静观若有得，知非降才殊。","但伤此道违，独行尝寡徒。","解后知我者，聊足以自娱。"]},{"t":"次韵李参政见遗生日 其一","f":"五言律诗","c":["六月不知暑，湖风涨晚林。","凭阑追旧梦，驰驿寄新吟。","出入三朝意，卷舒千古心。","感余不暇懒，窗影午蟾侵。"]},{"t":"次韵李参政龙鹤山庐 其三","f":"五言绝句","c":["莫使儿辈觉，从渠青紫纷。","马前金罢亚，鸟外玉奫沦。"]},{"t":"次韵李参政秋怀十绝 其九","f":"七言绝句","c":["止处流行息处生，春作夏长秋敷荣。","其间毫发皆帝力，民日用之无能名。"]},{"t":"次韵李参政秋怀十绝 其八","f":"七言绝句","c":["母心日日儿当归，屋山看尽乌鸟栖。","安得使我如乌飞，母旁衮地为儿啼。"]},{"t":"次韵李参政秋怀十绝 其十","f":"七言绝句","c":["新诗妙处古人过，节制场中老伏波。","枯肠亦知费搜搅，奈此风景触拨何。"]},{"t":"次韵李参政秋怀十绝 其七","f":"七言绝句","c":["河神不恤吾民勤，涛头射山危欲倾。","似闻凌云滩头水，前日肉薄几危城。"]},{"t":"次韵李参政湖上杂咏录寄龙鹤坟庐 其五","f":"五言古诗","c":["西山有佳人，惯踏山下路。","晨吟泽畔云，午睡岩前雨。","莫使儿辈觉，夺我林壑趣。"]},{"t":"次韵李参政湖上杂咏录寄龙鹤坟庐 其二","f":"五言古诗","c":["木落天宇空，野迥江水碧。","谁欤驱四运，昨夕复今夕。","君看瀛海内，寿考匪金石。"]},{"t":"次韵李参政湖上杂咏录寄龙鹤坟庐 其六","f":"五言古诗","c":["仲尼趋聘召，季路奚不怿。","分量固尔殊，何伤于遍历。","自揣或未能，莫如只坚白。"]},{"t":"次韵李参政湖上杂咏录寄龙鹤坟庐 其三","f":"五言古诗","c":["圣死微言湮，千载迷津涯。","浮骖遍八极，日暮犹伊鸦。","大道如掌平，人苦不识家。"]},{"t":"次韵李参政湖上杂咏录寄龙鹤坟庐 其七","f":"五言古诗","c":["皇天平四时，先春而后秋。","寒威夺仁气，惨惨纷百忧。","康世非我长，自许以一丘。"]},{"t":"次韵李参政湖上杂咏录寄龙鹤坟庐 其十三","f":"五言古诗","c":["世有傀儡棚，帐幕深遮围。","衣冠巧装饰，观者迷是非。","自谓真好手，不知若为归。"]},{"t":"次韵李参政湖上杂咏录寄龙鹤坟庐 其十一","f":"五言古诗","c":["大亨惟同人，小知仅私己。","皇皇万井封，耽耽百重陛。","尔痾寔余恫，须知本同体。"]},{"t":"次韵李参政湖上杂咏录寄龙鹤坟庐 其一","f":"五言古诗","c":["龙鹤在吾西，昔年班荆处。","乃今五斗米，絷之不得去。","冬夜那何晨，斜河耿高树。"]},{"t":"次韵李参政湖上杂咏录寄龙鹤坟庐 其十","f":"五言古诗","c":["江左忧佛狸，荆州忌老瞒。","既虞薪下火，又耻泥中蟠。","不虞复不耻，志士宁无叹。"]},{"t":"次韵李参政湖上杂咏录寄龙鹤坟庐 其九","f":"五言古诗","c":["百年狐兔窟，污我黄河流。","槃槃帝王州，仅与瓯脱侔。","秋风壮夫泪，禾黍莽平畴。"]},{"t":"次韵李参政湖上杂咏录寄龙鹤坟庐 其八","f":"五言古诗","c":["古人为己学，不以遇不遇。","学问思辨行，止定静安虑。","次序固晓然，人情苦伤遽。"]},{"t":"次韵李参政湖上杂咏录寄龙鹤坟庐 其十二","f":"五言古诗","c":["南园鼎盛时，纷纷车马迹。","须臾风景异，树老春寂历。","盛衰那可常，此理最明白。"]},{"t":"次韵李参政湖上杂咏录寄龙鹤坟庐 其四","f":"五言古诗","c":["南山高崔嵬，草树蔚乔林。","云横日曀曀，蝉鸣谷阴阴。","戛然丹凤咮，为我作好音。"]},{"t":"次韵李肩吾读易亭山茶梅","f":"五言古诗","c":["梅华鹤羽白，茶华鹤头红。","拱揖鹤山翁，始授宗人同。","山间两宾主，穷极造化功。","易终得未济，曹末观豳风。","或嗟生处远，不近扶木东。","谁知天然贵，正在阿堵中。","喧寂四时耳，寒至窒斯穹。","冷眼看千古，声色沈英熊。"]},{"t":"次韵李彭州乞鹤于虞万州 其一","f":"七言绝句","c":["急景应如赴壑鳞，感时心事可怜生。","湖边雁序殷勤叫，持寄新诗念故人。"]},{"t":"次韵李彭州访山居三绝 其二","f":"七言绝句","c":["古剡溪头寄短椽，山阴胜韵更谁传。","似闻昨夜高轩过，人怪儒衣住檐肩。"]},{"t":"次韵苏和父自郫见寄","f":"五言古诗","c":["敬共事明德，懔如槃水持。","岂惟将弗胜，抑恐浊且兹。","结发齿名官，几被末俗移。","学睎迁商博，文慕庄骚为。","书不记痴龙，诂不通雌霓。","耻于市朝挞，甚于沟壑挤。","大道砥如平，阽身蹈艰危。","迨其阅世久，始识真闻知。","天命贲草木，生意长萋萋。","蕃鲜固云乐，槁瘁安足悲。","阴阳孰信诎，日月谁荡推。","乾坤奠中极，雷泽周四陲。","夫人命于诚，地生而天施。","五行根五事，位育谁司之。","嬛浮溺于词，躁轻乱于仪。","山鸡衒清影，祇以速颠跻。","况彼膜外荣，皇皇复滋滋。","此于我何加，寒暑自四时。","苏公西南彦，仪鸿渐于逵。","而我坐远屏，七年堕蛮夷。","梦思岷山阳，枯筇伴庞眉。","人才日零落，憔悴西南维。","大篇忽开予，炯炯晨星垂。","公来何勇迈，我往何栖迟。","敢睎会温潞，窃愿商濂伊。","默嗟气相求，范喧蜜成脾。","梅边立踟蹰，正待阳春归。"]},{"t":"次韵叔衍兄贺生子","f":"七言律诗","c":["一壑一丘耕且为，不歆周网应非罴。","云霾障日树蒙密，草蔓漫天山蔽亏。","生意正从芽檗露，善根不逐斧斤斯。","溶溶此理谁能解，剩喜吾宗有白眉。"]},{"t":"次韵眉山胡宰喜雪","f":"七言律诗","c":["龙公试手发阴机，琐定愁云阵不飞。","老树垂垂低欲压，稚苗薿薿烂生辉。","穷冬莫厌诗筒数，富岁先占讼缿稀。","拟待明朝约清赏，剡溪兴尽酒船归。"]},{"t":"次韵赵制置制胜轩诗","f":"七言古诗","c":["何年误认貙作熊，力小知薄当戎冲。","级夷蕃拔牖户破，至今风色长如冬。","去年推毂以授公，单车飞度双剑峰。","风棱荦荦胆气雄，临淮军垒足迹重。","夜起揽衣瞻井络，铸铁不知经几错。","朅来谈笑上纹楸，龟头局中虎口著。","谁将舆柴误战尘，天戈一挥如砥平。","濯征猃狁威蛮荆，捷书夜上白玉京。","考成轩户适兹日，一吐十年胸怫郁。","看诗又觉饶馀力，要殄馀忧宽旰食。","书生喜极还太息，天下忧端尚非一。","经营分表竟何益，盍护本根保成绩。"]},{"t":"次韵郭方叔诸公借胡致堂赏梅至夜赋诗","f":"词","c":["玄阴作秋冬，杀气寓风雪。","土深候虫闭，山静飞鸟绝。","谁知无边春，万古长不灭。","或畅然以舒，或凝然以结。","或聚为融和，或散为骚屑。","又尝以此观诸人，生意不断长如薰。","咸阳宫殿气成雾，忽作芒砀山泽云。","神爵甘露来纷纷，画堂已入王政君。","人从动后观变态，谁于起处探絪缊。","浅者若为见，夜气长如神。","傥知起灭幻，便省消息真。","如何天机之浅者，但识人间桃李春。"]},{"t":"次韵黄判官喜雪","f":"七言律诗","c":["天马流行泽上坤，玉龙飞洒水边村。","扶持农扈培邦本，排荡阴机立岁元。","遍地诗材供墨客，通宵酒令属侯门。","却怜赤子无衣褐，仰面苍苍叹少恩。"]},{"t":"次韵黄侍郎海棠花下怯黄昏七绝 其一","f":"五言绝句","c":["狂风利剑戟，火龙困屠宰。","莫起落红愁，生意浩云海。"]},{"t":"次韵黄侍郎海棠花下怯黄昏七绝 其七","f":"五言绝句","c":["醉妃索南内，玉奴毙东昏。","所以观物心，皇皇妙无门。"]},{"t":"次韵黄侍郎海棠花下怯黄昏七绝 其五","f":"五言绝句","c":["稚绿茁儿拳，老红面百摺。","诗坛更伏波，令我逢敌怯。"]}]};